window.PYTHON_COURSES = [{"id":"python-ch01","slug":"ch01","number":1,"title":"프로그램을 읽고 실행하기","description":"입력과 처리, 코드와 출력, 실행과 오류의 차이를 작은 프로그램으로 이해합니다.","prerequisite":"처음 시작해도 괜찮아요.","runtime":"Python 3","testedVersion":"3.12.14","lessons":[{"id":"python-l001","order":1,"title":"프로그램·명령·실행 결과","subtitle":"주어진 데이터에 어떤 일을 해서 어떤 결과를 만들지, 세 부분으로 읽어 봅니다.","minutes":7,"goal":"작은 프로그램에서 사용하는 데이터, 처리 과정, 출력 결과를 구분한다.","intro":"컴퓨터에게 ‘알아서 잘 계산해 줘’라고만 말하면 무엇을 계산할지 정해지지 않습니다. 사용할 값과 해야 할 일을 정확하게 적어야 합니다. 프로그래밍의 첫걸음은 낯선 기호를 외우는 것보다, 내가 원하는 결과까지의 과정을 나누어 보는 데 있습니다.","sections":[{"title":"프로그램은 실행할 일을 적은 절차입니다","body":["프로그램은 컴퓨터가 수행할 일을 정해진 문법으로 적은 것입니다. 파이썬으로 적은 프로그램의 글을 파이썬 코드라고 합니다. 사람에게 부탁하는 말과 달리, 코드에서는 기호와 순서에 정해진 뜻이 있습니다.","아래의 print(...)는 괄호 안의 값을 화면의 출력 영역에 보여 달라는 요청입니다. 따옴표로 둘러싼 부분은 글자 내용입니다. 아직 괄호와 따옴표를 모두 외울 필요는 없습니다. 지금은 두 요청이 실행되면 두 줄의 결과가 나온다는 관계부터 살펴보세요."],"code":{"source":"print(\"준비\")\nprint(\"시작\")","kind":"python","output":"준비\n시작","error":null,"caption":"코드는 할 일이고, 출력은 그 일을 실행한 뒤 나타나는 결과입니다."}},{"title":"데이터와 처리를 나누면 코드가 읽힙니다","body":["입력은 프로그램이 작업에 사용하는 데이터를 받아들이는 쪽, 처리는 그 데이터로 계산하거나 판단하는 일, 출력은 만들어진 결과를 밖으로 내보내는 쪽입니다. 계산기에서 1200과 800을 받아 더한 뒤 2000을 보여 주는 상황을 떠올리면 됩니다.","아래 코드는 키보드에서 값을 새로 받지 않습니다. 사용할 숫자 1200과 800을 코드 안에 미리 적었습니다. 이 숫자들은 계산할 데이터이고, +는 더하는 처리이며, print는 계산된 값을 출력합니다. 입력을 받는 방식은 여러 가지이므로 모든 프로그램이 실행할 때마다 사람의 입력을 기다리는 것은 아닙니다."],"code":{"source":"print(1200 + 800)","kind":"python","output":"2000","error":null,"caption":"먼저 1200 + 800의 값이 계산되고, print가 그 값 2000을 보여 줍니다."}},{"title":"코드와 결과는 서로 다른 것입니다","body":["print(1200 + 800)라는 글 전체가 화면에 나오는 것은 아닙니다. 파이썬은 이 코드를 지시로 해석하여 덧셈을 한 뒤 결과를 출력합니다. 코드를 읽을 때는 ‘어떤 글이 적혀 있나’에서 한 걸음 더 나아가 ‘이 지시가 실행되면 무엇이 나타날까’를 생각해야 합니다.","출력은 화면에 나타나는 글자만 뜻하지도 않습니다. 사진을 받아 크기를 줄이고 새 파일로 저장하는 프로그램이라면, 입력은 원본 사진이고 처리는 크기 변경이며 출력은 새 사진 파일입니다. 이 챕터에서는 결과를 쉽게 확인할 수 있도록 화면 출력부터 사용합니다."]}],"worked":{"question":"1000원짜리 물건과 500원짜리 물건을 하나씩 산 금액을 보여 주려면, 아래 코드를 어떻게 읽으면 될까요?","code":{"source":"print(1000 + 500)","kind":"python","output":"1500","error":null,"caption":"출력에는 단위인 ‘원’을 따로 적지 않았으므로 숫자 1500만 나타납니다."},"steps":["계산할 데이터는 코드 안에 적힌 1000과 500입니다. 별도의 키보드 입력은 없습니다.","+가 두 수를 더합니다. 이 식의 값은 1500입니다.","print가 계산된 값을 출력합니다. 식 자체나 ‘원’이라는 글자를 자동으로 덧붙이지 않습니다."],"answer":"데이터 1000과 500에 덧셈을 적용하여 1500을 출력하는 프로그램입니다."},"misconception":{"question":"실행할 때 키보드로 입력하지 않으면 입력 데이터가 없는 건가요?","answer":"사람이 매번 타이핑해야만 프로그램이 데이터를 사용할 수 있는 것은 아닙니다. 코드에 미리 적은 값, 읽어 온 파일, 다른 프로그램이 보낸 값도 작업에 사용됩니다. 다만 print(1000 + 500)에는 외부에서 새 값을 받아들이는 동작이 없다는 점은 구분해야 합니다."},"keypoints":["코드는 할 일을 적은 글이고, 실행 결과는 그 지시를 수행한 뒤 나타나는 것입니다.","사용할 데이터, 데이터를 다루는 처리, 밖으로 내보내는 출력을 나누어 읽습니다.","print(...)는 괄호 안의 값을 출력하며, 키보드 입력을 받는 명령은 아닙니다."],"examples":[{"question":"본문의 print(...)는 괄호 안의 값을 출력합니다. 아래 코드를 직접 적고, 실행하면 어떤 한 줄이 나올지 먼저 예상해 보세요. 실행 결과와 코드 자체가 어떻게 다른지도 한 문장으로 적어 보세요.","skill":"코드와 실행 결과","solution":{"answer":"출력은 5입니다. 코드는 덧셈과 출력을 요청하는 글이고, 화면에는 그 요청을 수행한 결과가 나타납니다.","code":{"source":"print(2 + 3)","kind":"python","output":"5","error":null}},"explanation":"2 + 3을 계산한 값이 print에 전달됩니다. print라는 이름과 괄호, 식 전체를 그대로 출력하는 것은 아닙니다.","code":"print(2 + 3)","codeKind":"python"},{"question":"1000원짜리 물건과 500원짜리 물건을 하나씩 산 금액을 계산해 출력하는 코드 한 줄을 작성하세요. 사용할 두 숫자, 처리할 일, 예상 출력을 각각 적은 뒤 확인해 보세요. 출력에는 원이라는 단위를 붙이지 않습니다.","skill":"데이터·처리·출력 구분","solution":{"answer":"사용할 데이터는 1000과 500, 처리는 덧셈, 출력은 1500입니다. 아래는 코드의 한 가지 예시입니다.","code":{"source":"print(1000 + 500)","kind":"python","output":"1500","error":null}},"explanation":"코드에 계산할 숫자를 미리 적고 +로 더합니다. print는 계산 결과를 보여 주며 단위를 자동으로 덧붙이지 않습니다."},{"question":"아래 두 줄을 직접 적은 다음, 마지막 줄에 끝이라는 글자를 출력하는 요청을 하나 더 적어 보세요. 본문처럼 print와 따옴표를 사용하고, 세 줄의 결과가 나오는지 확인하세요.","skill":"출력 요청 추가","solution":{"answer":"준비, 시작, 끝이 각각 한 줄씩 나타납니다. 아래는 큰따옴표를 사용한 예시입니다.","code":{"source":"print(\"준비\")\nprint(\"시작\")\nprint(\"끝\")","kind":"python","output":"준비\n시작\n끝","error":null}},"explanation":"화면에 보일 글자는 따옴표 안에 적습니다. 이 프로그램은 적힌 순서대로 세 번의 출력 요청을 수행합니다.","code":"print(\"준비\")\nprint(\"시작\")","codeKind":"python"},{"question":"아래 코드를 직접 적어 실행하고, 숫자 7만 9로 바꾸어 다시 확인하세요. 바꾸기 전과 후의 출력을 적고, 실행할 때 사람에게 숫자를 묻지 않아도 되는 이유를 설명해 보세요.","skill":"데이터가 주어지는 방식","solution":{"answer":"처음에는 8, 숫자를 바꾼 뒤에는 10이 나옵니다. 사용할 숫자가 코드 안에 이미 적혀 있으므로 새 값을 입력받을 필요가 없습니다.","code":{"source":"print(9 + 1)","kind":"python","output":"10","error":null,"caption":"7을 9로 바꾼 뒤의 코드와 결과입니다."}},"explanation":"print는 값을 출력하는 기능입니다. 여기에는 키보드로 숫자를 받는 동작이 없으며, 코드에 적어 둔 숫자를 계산에 사용합니다.","code":"print(7 + 1)","codeKind":"python"},{"question":"더하고 싶은 숫자 두 개를 정하세요. 본문의 print(1200 + 800)과 같은 모양으로 코드를 직접 작성하고, 예상한 합과 실제 출력을 비교해 보세요. 사용한 두 숫자도 함께 적으세요.","skill":"새 데이터로 적용","solution":{"answer":"예를 들어 200과 300을 골랐다면 합은 500입니다. 숫자는 자유롭게 정해도 되며, 자신이 적은 두 수의 합이 출력되면 됩니다.","code":{"source":"print(200 + 300)","kind":"python","output":"500","error":null,"caption":"200과 300을 고른 경우의 예시입니다."}},"explanation":"계산할 데이터가 달라져도 두 수를 더한 뒤 출력하는 원리는 같습니다. 아래 코드는 가능한 답의 한 가지입니다."}]},{"id":"python-l002","order":2,"title":"인터프리터와 코드 파일","subtitle":"코드를 적는 곳과 실행하는 곳을 구분하면, 같은 프로그램을 다시 실행할 수 있습니다.","minutes":10,"goal":"대화형 실행과 저장한 코드 파일의 실행을 구분하고, 짧은 .py 파일을 실행하는 과정을 설명한다.","intro":"첫 레슨에서는 코드와 출력 결과를 나누어 보았습니다. 그런데 코드를 메모장에 적는 것만으로는 계산 결과가 나타나지 않습니다. 코드를 읽고 실행하는 파이썬 인터프리터가 필요합니다. 이 레슨에서는 코드를 적는 글과 그것을 실행하는 프로그램을 연결해 봅니다.","sections":[{"title":"편집기는 코드를 적고, 인터프리터는 실행합니다","body":["코드 편집기는 프로그램의 글을 만들고 고치는 도구입니다. 파이썬 인터프리터는 그 글을 파이썬의 규칙에 따라 해석하고 실행하는 프로그램입니다. 하나의 개발 도구에 편집기와 실행 기능이 함께 들어 있어도 두 역할은 구분할 수 있습니다.","직접 실행하려면 PC에 Python 3 실행 환경이 있어야 합니다. Windows와 macOS는 python.org/downloads에서 자신의 운영체제에 맞는 공식 안내를 따라 준비할 수 있습니다. Linux는 배포판에서 제공하는 Python 3 설치 안내를 따릅니다. 이 사이트에서는 설치 없이 코드와 예상 결과를 읽을 수 있으며, 코드 블록 자체가 실행기는 아닙니다."]},{"title":"대화형 실행은 작은 확인에 편리합니다","body":["IDLE의 Shell 창을 열거나, 터미널에 Windows에서는 py, macOS·Linux에서는 python3만 입력하면 대화형 실행을 시작할 수 있습니다. 보통 >>> 표시가 나타나는데, 이는 ‘다음 코드를 입력해도 된다’는 안내인 프롬프트입니다. 코드의 일부가 아니므로 직접 입력하거나 코드 파일에 복사하지 않습니다. 아래 기록에서 >>> 뒤의 글이 입력한 코드이고, 표시가 없는 다음 줄이 결과입니다.","대화형 모드에서는 2 + 3처럼 값을 계산하는 식을 입력하면 그 값이 곧바로 보입니다. print(...)를 입력해 값을 명시적으로 출력할 수도 있습니다. 계산 하나나 짧은 코드를 확인하기 좋지만, 다시 사용할 프로그램은 파일로 저장하는 편이 편리합니다."],"code":{"source":">>> 2 + 3\n5\n>>> print(\"안녕\")\n안녕","kind":"console","caption":"대화형 창의 기록입니다. >>>와 출력 결과를 코드 파일에 함께 붙여 넣지 않습니다."}},{"title":"파일은 다시 실행할 코드를 모아 둡니다","body":["파이썬 코드를 일반 텍스트 파일에 적고 hello.py처럼 .py로 끝나는 이름으로 저장할 수 있습니다. 이 파일을 실행하도록 요청하면 인터프리터가 저장된 내용을 읽습니다. 문서 편집기의 화면을 고친 것과 파일에 저장한 것은 다를 수 있으므로, 고친 뒤에는 저장하고 다시 실행해야 합니다.","파일 실행에서는 계산식만 적었다고 그 값이 자동으로 화면에 나타나지 않습니다. 아래 파일의 첫 줄도 2 + 3을 계산하지만, 출력 요청은 두 번째 줄의 print에만 있습니다. 따라서 5가 한 번만 출력됩니다. 또 파일을 실행할 때는 그 파일의 문법을 먼저 분석하므로, ‘언제나 한 줄을 읽는 즉시 실행한다’고 이해하지 않아야 합니다. 문법 오류가 있는 경우는 레슨 5에서 살펴봅니다."],"code":{"source":"2 + 3\nprint(2 + 3)","kind":"python","output":"5","error":null,"caption":".py 파일로 실행했을 때의 결과입니다. 대화형 창에 식을 입력했을 때와 구분합니다."}},{"title":"첫 파일은 저장하고, 실행하고, 다시 고칩니다","body":["설치된 환경에 IDLE이 있다면 이를 열고 File → New File로 편집 창을 만듭니다. 아래 풀이 예시의 두 줄을 적고 File → Save로 hello.py에 저장한 뒤 Run → Run Module을 선택합니다. 결과는 IDLE의 Shell 창에서 확인합니다. 편집 창의 코드와 Shell 창의 결과를 오가며 비교해 보세요.","터미널은 운영체제에 실행할 프로그램과 파일을 글로 전달하는 창입니다. 터미널을 사용하는 경우 먼저 hello.py를 저장한 폴더에서 창을 열고, Windows에서 py --version으로 Python 3.x가 표시되는지 확인한 뒤 py hello.py를 실행합니다. macOS·Linux에서는 각각 python3 --version과 python3 hello.py를 사용합니다. 실행 명령이 없다고 나오면 설치 환경부터 확인합니다.","py hello.py와 python3 hello.py는 운영체제의 터미널에 입력하는 실행 명령입니다. 파이썬의 >>> 뒤나 hello.py 파일 안에 쓰는 코드가 아닙니다. 대화형 창에서 터미널로 돌아가야 한다면 quit()를 입력해 대화형 실행을 마칠 수 있습니다. 파일을 못 찾았다는 메시지가 나오면 파일 이름과 터미널이 열린 폴더를 먼저 비교합니다."],"code":{"source":"py --version\npy hello.py","kind":"console","caption":"Windows 터미널에서 Python 3 설치를 확인하고 파일을 실행하는 명령입니다. macOS·Linux에서는 py 대신 python3를 사용합니다."}}],"worked":{"question":"hello.py 파일에 아래 코드를 저장했습니다. 파일을 실행하고, 인사말을 바꾼 뒤 다시 확인하는 과정을 따라가 보세요.","code":{"source":"print(\"안녕\")\nprint(2 + 3)","kind":"python","output":"안녕\n5","error":null,"caption":"hello.py에 저장할 파이썬 코드입니다. 실행 명령이나 >>> 표시는 넣지 않습니다."},"steps":["코드만 hello.py에 저장하고, IDLE의 Run Module 또는 터미널의 파일 실행 명령으로 인터프리터에 실행을 요청합니다.","첫 print는 안녕을, 두 번째 print는 덧셈 결과 5를 출력합니다. 두 줄의 코드를 실행하여 두 줄의 출력을 얻습니다.","첫 줄의 안녕을 반가워로 고쳤다면 파일을 다시 저장한 뒤 실행합니다. 첫 출력이 반가워로 달라지고 두 번째 출력 5는 유지되는지 확인합니다."],"answer":"작성 → 저장 → 실행 → 결과 확인의 흐름을 반복합니다. 파일 이름, 저장된 내용, 실행 결과를 함께 확인해야 바꾼 코드가 반영됐는지 알 수 있습니다."},"misconception":{"question":"대화형 창에서 2 + 3은 5가 보였는데, 같은 식만 적은 파일에서는 왜 조용한가요?","answer":"대화형 모드는 입력한 식의 값을 보여 주는 기능이 있습니다. 일반적인 파일 실행에서는 그 자동 표시를 하지 않습니다. 계산에 실패한 것이 아니라 결과를 보여 달라는 요청이 없는 것이므로, 화면에서 확인하려면 print(2 + 3)처럼 출력합니다."},"keypoints":["편집기는 코드를 작성·저장하고, 인터프리터는 그 코드를 해석·실행합니다.",">>>는 대화형 창의 안내 표시이며 코드 파일이나 실행 명령의 일부가 아닙니다.","파일의 계산 결과를 보려면 출력 요청이 필요하며, 수정한 코드는 저장한 뒤 다시 실행합니다."],"examples":[{"question":"아래 대화형 창의 기록에서 실행할 코드만 골라 hello.py에 직접 적으세요. >>>와 이미 나온 결과는 옮기지 않습니다. 파일을 저장하고 실행해 같은 결과가 나오는지 확인하세요.","skill":"프롬프트와 코드 구분","solution":{"answer":"hello.py에는 print(6 + 2) 한 줄만 저장합니다. 파일을 실행하면 8이 출력됩니다.","code":{"source":"print(6 + 2)","kind":"python","output":"8","error":null,"caption":"hello.py에 저장할 내용입니다."}},"explanation":">>>는 입력을 기다리는 표시이고, 그 다음 줄의 8은 결과입니다. 파일에 필요한 것은 실행할 파이썬 코드입니다.","code":">>> print(6 + 2)\n8","codeKind":"console","codeLabel":"대화형 창의 기록"},{"question":"아래 두 줄을 hello.py에 적어 저장하고 실행하세요. 8이 몇 번 나타날지 먼저 예상해 보세요. 이어서 대화형 창에 6 + 2만 입력했을 때와 비교해 차이를 적으세요.","skill":"대화형 실행과 파일 실행","solution":{"answer":"파일에서는 8이 한 번만 출력됩니다. 대화형 창에서는 6 + 2만 입력해도 계산값 8을 보여 줍니다.","code":{"source":"6 + 2\nprint(6 + 2)","kind":"python","output":"8","error":null,"caption":"두 줄을 하나의 파일로 실행한 결과입니다."}},"explanation":"파일은 식의 값을 자동으로 화면에 표시하지 않으므로 print가 있는 두 번째 줄에서만 출력합니다. 대화형 모드에는 입력한 식의 값을 보여 주는 기능이 있습니다.","code":"6 + 2\nprint(6 + 2)","codeKind":"python"},{"question":"hello.py라는 새 파일에 첫 줄은 안녕, 다음 줄은 2 + 3의 계산 결과를 출력하는 코드를 직접 작성하세요. 저장한 뒤 IDLE의 Run Module이나 본문에서 안내한 터미널 명령으로 실행해 보세요.","skill":"작성·저장·실행","solution":{"answer":"안녕과 5가 각각 한 줄씩 나타나면 됩니다. 아래는 파일에 적을 수 있는 코드의 한 가지 예시입니다.","code":{"source":"print(\"안녕\")\nprint(2 + 3)","kind":"python","output":"안녕\n5","error":null}},"explanation":"편집기에 코드를 적는 것과 실행하는 것은 다른 단계입니다. 저장한 파일을 인터프리터로 실행해야 출력 결과를 확인할 수 있습니다."},{"question":"hello.py에 아래 코드를 저장해 실행하세요. 편집기에서 처음을 수정으로 바꾼 뒤 저장하고 다시 실행해 보세요. 결과가 계속 처음으로 보인다면 무엇부터 확인할지도 적으세요.","skill":"수정·저장·재실행","solution":{"answer":"다시 실행한 결과는 수정입니다. 이전 결과가 나오면 수정 내용을 저장했는지와 같은 위치의 hello.py를 실행했는지 확인합니다.","code":{"source":"print(\"수정\")","kind":"python","output":"수정","error":null,"caption":"수정한 내용을 저장한 뒤 실행합니다."}},"explanation":"파일 실행은 편집 화면이 아니라 저장된 내용을 읽습니다. 파일 이름이 같아도 다른 폴더에 있는 파일을 실행하면 수정이 반영되지 않을 수 있습니다.","code":"print(\"처음\")","codeKind":"python"},{"question":"hello.py에 아래 코드를 저장했습니다. 그 파일이 있는 폴더의 터미널에서 실행하려고 합니다. 자신의 운영체제에 맞는 실행 명령을 직접 적고 실행해 보세요. 파이썬의 >>> 창과 운영체제 터미널을 구분하세요.","skill":"실행 명령의 위치","solution":{"answer":"Windows에서는 py hello.py, macOS·Linux에서는 python3 hello.py를 입력합니다. 출력은 실행 성공입니다. >>>가 보이는 파이썬 대화형 창에 있다면 quit()로 마친 뒤 운영체제 터미널에서 명령을 입력합니다."},"explanation":"py 또는 python3는 실행할 인터프리터이고 hello.py는 읽을 파일입니다. 실행 명령을 hello.py 안에 쓰지 않습니다. 명령을 찾지 못하면 본문의 설치 환경 안내를 확인합니다.","code":"print(\"실행 성공\")","codeKind":"python","codeLabel":"hello.py에 저장된 코드"}]},{"id":"python-l003","order":3,"title":"첫 출력과 문자열 리터럴","subtitle":"코드에 적는 표시와 화면에 나타나는 값을 나누어 봅니다.","minutes":8,"goal":"문자열을 감싸는 따옴표와 실제 문자 값을 구분하고 print의 출력을 예측한다.","intro":"화면에 인사말을 보여 주려면 컴퓨터에 무엇을 적어야 할까요? 코드에는 print, 괄호, 따옴표까지 있지만 화면에는 인사말만 나타납니다. 이 차이는 기호가 사라진 실수가 아니라, 각 기호가 맡은 역할이 다르기 때문에 생깁니다.","sections":[{"title":"print는 값을 화면으로 보내는 요청입니다.","body":["print는 Python에 기본으로 준비된 함수입니다. 함수는 맡겨진 일을 수행하도록 부르는 기능이라고 생각하면 됩니다. 지금은 함수를 직접 만드는 법보다, print 뒤의 괄호 안에 보여 줄 값을 넣는 사용법부터 익힙니다.","print(\"안녕하세요\")에서 print는 출력할 기능의 이름, 괄호는 그 기능에 전달할 값을 둘 자리입니다. 실행되면 안녕하세요라는 글자가 나타나고 기본적으로 줄이 바뀝니다. 다음 print의 결과가 다음 줄에 보이는 이유입니다."],"code":{"source":"print(\"안녕하세요\")\nprint(\"반가워요\")","kind":"python","output":"안녕하세요\n반가워요","error":null,"caption":"코드의 괄호와 print라는 이름은 출력되지 않습니다. 두 번의 출력이 두 줄에 나타납니다."}},{"title":"따옴표는 문자열의 시작과 끝을 표시합니다.","body":["문자열은 글자들을 하나의 값으로 다루는 자료입니다. \"안녕\"처럼 원하는 문자 값을 코드에 직접 적은 표현을 문자열 리터럴이라고 부릅니다. 바깥의 따옴표는 Python에게 어디부터 어디까지가 그 문자 값인지 알려 주는 경계 표시입니다.","작은따옴표와 큰따옴표 모두 사용할 수 있지만, 하나의 문자열은 시작한 종류와 같은 따옴표로 닫아야 합니다. 아래 두 줄은 같은 문자 값을 print에 전달하므로 같은 결과를 만듭니다. 코드에는 일반 작은따옴표(')나 큰따옴표(\")를 사용하고, 문서용으로 굽은 따옴표를 대신 넣지 않습니다."],"code":{"source":"print('안녕')\nprint(\"안녕\")","kind":"python","output":"안녕\n안녕","error":null,"caption":"두 표현에서 값은 모두 안녕입니다. 바깥 따옴표의 모양이 출력 내용을 바꾸지는 않습니다."}},{"title":"따옴표 안의 계산식도 글자입니다.","body":["같은 2 + 3이라는 모양이라도 따옴표 안에 있으면 문자 값입니다. Python은 그 안의 더하기 기호를 계산 명령으로 읽지 않습니다. 반대로 따옴표 없이 2 + 3을 적으면 수의 덧셈을 계산하고 그 결과를 print에 전달합니다.","그래서 출력을 예상할 때는 먼저 괄호 안이 글자를 직접 적은 표현인지, 값을 계산하는 식인지 살펴봅니다. print가 계산식의 글자를 마음대로 바꾸는 것이 아닙니다. 두 줄은 print에 전달되는 값부터 다릅니다."],"code":{"source":"print(\"2 + 3\")\nprint(2 + 3)","kind":"python","output":"2 + 3\n5","error":null,"caption":"첫 줄은 글자를 그대로, 둘째 줄은 계산한 값을 출력합니다."}},{"title":"문자열 안에 넣을 따옴표는 내용으로 남습니다.","body":["출력할 문장 자체에 작은따옴표가 들어갈 수도 있습니다. 그때 바깥을 큰따옴표로 감싸면, 안쪽 작은따옴표가 문자열을 끝내지 않습니다. 반대로 문장 안에 큰따옴표를 넣으려면 바깥을 작은따옴표로 감쌀 수 있습니다.","아래 문장에서 바깥 경계와 안쪽 내용을 각각 찾아보세요. print가 모든 따옴표를 삭제하는 것은 아닙니다. 경계 표시는 문자 값에 포함되지 않지만, 문자 값 안에 넣은 따옴표는 다른 글자처럼 출력됩니다."],"code":{"source":"print(\"I'm learning Python.\")\nprint('그는 \"안녕\"이라고 말했다.')","kind":"python","output":"I'm learning Python.\n그는 \"안녕\"이라고 말했다.","error":null,"caption":"경계로 쓰지 않은 안쪽 따옴표는 출력 내용에 포함됩니다."}}],"worked":{"question":"아래 세 줄을 파일에 저장해 실행하면 무엇이 보일까요? 각 줄에서 print에 전달되는 값부터 구분해 봅시다.","code":{"source":"print(\"계산 결과\")\nprint(3 + 4)\nprint(\"3 + 4\")","kind":"python","output":"계산 결과\n7\n3 + 4","error":null,"caption":"같은 더하기 표시가 계산에 쓰일 때와 글자에 쓰일 때를 비교합니다."},"steps":["첫 줄의 큰따옴표는 계산 결과라는 문자 값의 경계입니다. 화면에는 그 글자만 나타납니다.","둘째 줄의 3 + 4에는 따옴표가 없으므로 먼저 7을 계산합니다. print는 그 값을 보여 줍니다.","셋째 줄은 따옴표 안의 글자를 전달합니다. 따라서 계산하지 않고 3 + 4를 보여 줍니다. 각 print 뒤에는 기본 줄바꿈이 생깁니다."],"answer":"출력은 계산 결과, 7, 3 + 4의 세 줄입니다. 코드의 모습과 전달되는 값을 구분하면 결과를 설명할 수 있습니다."},"misconception":{"question":"print는 따옴표를 전부 지우는 기능인가요?","answer":"아닙니다. 문자열 바깥의 따옴표는 값의 경계이므로 애초에 문자 값에 포함되지 않습니다. 값 안에 넣은 따옴표는 그대로 출력될 수 있습니다. 또 print(\"5\")와 print(5)는 둘 다 화면에 5를 보여 주므로, 출력 모양만으로 원래 값이 문자열인지 숫자인지 항상 알 수 있는 것도 아닙니다."},"keypoints":["문자열 리터럴은 문자 값을 코드에 직접 적은 표현이며, 바깥 따옴표는 그 값의 경계입니다.","print는 전달받은 값을 보여 줍니다. 따옴표 안의 식은 글자이고, 밖의 계산식은 계산한 값을 전달합니다.","한 문자열의 시작과 끝은 같은 종류의 따옴표로 맞춥니다. 내용 안에 있는 따옴표는 출력될 수 있습니다."],"examples":[{"question":"아래 코드의 출력을 먼저 예상하고 직접 실행하세요. 이어서 바깥의 큰따옴표를 모두 작은따옴표로 바꾸어 다시 실행해 보세요. 출력이 달라지는지와 그 이유를 적으세요.","skill":"문자열의 경계","solution":{"answer":"두 코드 모두 안녕을 출력합니다. 시작과 끝의 따옴표 종류를 맞추면 큰따옴표와 작은따옴표로 같은 문자열을 나타낼 수 있습니다.","code":{"source":"print('안녕')","kind":"python","output":"안녕","error":null,"caption":"작은따옴표로 바꾼 예시입니다."}},"explanation":"문자열을 감싸는 바깥 따옴표는 내용의 경계입니다. 그 경계 표시는 문자 값에 포함되지 않아 출력되지 않습니다.","code":"print(\"안녕\")","codeKind":"python"},{"question":"Python 다음 줄에 공부 시작을 출력하는 코드를 작성하세요. print를 두 번 사용하고, 코드의 이름이나 바깥 따옴표가 결과에 나타나지 않는지도 확인해 보세요.","skill":"문자열 출력 작성","solution":{"answer":"Python과 공부 시작이 두 줄로 나타나면 됩니다. 큰따옴표 또는 작은따옴표를 짝에 맞게 사용할 수 있습니다.","code":{"source":"print(\"Python\")\nprint(\"공부 시작\")","kind":"python","output":"Python\n공부 시작","error":null}},"explanation":"각 print는 괄호 안의 문자열 값을 출력하고 기본적으로 줄을 바꿉니다. 기능 이름과 괄호는 출력할 내용이 아닙니다."},{"question":"아래 두 줄의 출력을 줄바꿈까지 먼저 적어 보세요. 코드를 직접 입력해 실행한 뒤, 같은 6 + 1이 왜 서로 다른 결과를 만드는지 설명하세요.","skill":"문자와 계산의 구분","solution":{"answer":"첫 줄에는 6 + 1, 둘째 줄에는 7이 나타납니다.","code":{"source":"print(\"6 + 1\")\nprint(6 + 1)","kind":"python","output":"6 + 1\n7","error":null}},"explanation":"첫 줄의 따옴표 안은 문자 내용이므로 계산하지 않습니다. 둘째 줄에는 숫자와 덧셈이 적혀 있으므로 계산한 값 7을 출력합니다.","code":"print(\"6 + 1\")\nprint(6 + 1)","codeKind":"python"},{"question":"아래 코드는 시작과 끝의 따옴표가 다릅니다. 따옴표를 고쳐 안녕을 출력하는 코드로 만들고 실행해 보세요. 어느 부분을 고쳤는지도 적으세요.","skill":"문자열 구문 수정","solution":{"answer":"끝의 작은따옴표를 큰따옴표로 바꾸면 됩니다. 반대로 시작을 작은따옴표로 맞추는 방법도 가능합니다.","code":{"source":"print(\"안녕\")","kind":"python","output":"안녕","error":null,"caption":"두 따옴표를 큰따옴표로 맞춘 예시입니다."}},"explanation":"문자열의 시작과 끝을 같은 종류의 따옴표로 표시해야 합니다. print의 괄호도 한 쌍으로 닫혀 있어야 합니다.","code":"print(\"안녕')","codeKind":"python"},{"question":"화면에 He's ready.를 한 줄로 출력하는 코드를 작성하세요. 문장 안의 작은따옴표와 마침표도 그대로 보여야 합니다. 바깥을 어떤 따옴표로 감싸면 되는지 생각해 보세요.","skill":"따옴표가 있는 문장 적용","solution":{"answer":"바깥을 큰따옴표로 감싸면 문장 속 작은따옴표를 내용으로 넣을 수 있습니다. 아래는 가능한 코드의 한 가지입니다.","code":{"source":"print(\"He's ready.\")","kind":"python","output":"He's ready.","error":null}},"explanation":"바깥 큰따옴표는 문자열의 경계를 나타내고, 안쪽 작은따옴표는 문자 값에 남습니다. 바깥 따옴표까지 출력할 필요는 없습니다."}]},{"id":"python-l004","order":4,"title":"순서·들여쓰기·주석","subtitle":"줄의 순서는 실행 흐름을, 들여쓰기는 코드가 속한 묶음을 알려 줍니다.","minutes":9,"goal":"짧은 코드에서 실행 순서, 들여쓰기 블록, 주석과 문자열 속 #을 구분한다.","intro":"같은 print 세 줄이라도 순서를 바꾸면 화면에 나타나는 이야기가 달라집니다. 줄 앞의 공백이나 #도 각각 맡은 역할이 있습니다. 코드를 글자 목록으로만 보지 않고, 실행할 순서와 함께 묶인 부분을 읽어 봅시다.","sections":[{"title":"먼저 실행한 출력이 먼저 나타납니다.","body":["조건이나 반복이 없는 아래 파일에서는 print가 위에서 아래로 실행됩니다. 시작을 출력한 뒤 준비를 출력하고, 마지막에 끝을 출력합니다. 코드를 읽을 때는 이미 실행한 줄과 다음에 실행할 줄을 나누어 생각해 보세요.","여기서 위에서 아래로 실행된다는 말은 파일의 문법 검사를 건너뛰고 한 줄씩 무조건 실행한다는 뜻은 아닙니다. 파일 실행에서는 코드가 문법에 맞는지 먼저 분석합니다. 문법 오류와 실행 중 오류의 차이는 다음 레슨에서 확인합니다."],"code":{"source":"print(\"시작\")\nprint(\"준비\")\nprint(\"끝\")","kind":"python","output":"시작\n준비\n끝","error":null,"caption":"이 예시는 조건과 반복이 없는 순차 실행입니다. 줄의 순서와 출력 순서를 나란히 읽어 보세요."}},{"title":"들여쓰기는 같은 블록에 속한다는 표시입니다.","body":["블록은 어떤 문장에 속해 함께 묶인 코드입니다. 이를 보기 위해 if True:라는 문장을 잠깐 사용하겠습니다. True는 참이라는 값이고, 이 예시의 if True:는 뒤에 들여쓴 블록을 실행한다는 뜻입니다. 조건에 따라 선택하는 자세한 규칙은 뒤의 조건 챕터에서 배웁니다.","콜론(:) 다음 줄의 print 두 개는 같은 너비로 들여썼으므로 같은 블록에 속합니다. 마지막 print는 왼쪽으로 돌아왔으므로 그 블록 밖에 있습니다. Python에서는 이 위치 관계가 코드의 구조이므로, 보기 좋게 만들려고 줄 앞의 공백을 마음대로 바꾸면 안 됩니다."],"code":{"source":"print(\"밖에서 시작\")\nif True:\n    print(\"블록의 첫 줄\")\n    print(\"블록의 둘째 줄\")\nprint(\"블록 밖에서 끝\")","kind":"python","output":"밖에서 시작\n블록의 첫 줄\n블록의 둘째 줄\n블록 밖에서 끝","error":null,"caption":"들여쓴 두 줄만 if True:에 속합니다. 여기서는 조건이 참이어서 두 줄이 순서대로 실행됩니다."}},{"title":"같은 깊이는 맞추고, 이 강좌에서는 공백 4칸을 씁니다.","body":["한 블록의 같은 깊이에 있는 줄은 들여쓰기 너비를 맞춰야 합니다. 블록을 시작하는 문장도 없는데 파일 맨 위의 print 앞에 공백을 붙이면, Python은 이유 없이 들여쓴 줄로 판단할 수 있습니다. 아래 코드는 그 때문에 실행되지 않는 예시입니다.","공백 4칸은 널리 쓰이는 Python 스타일 권장이며 이 강좌에서도 따릅니다. 문법이 모든 블록에 정확히 4칸만 허용한다는 뜻은 아닙니다. 지금은 공백을 사용하고 같은 깊이를 일관되게 맞추세요. 탭과 공백을 섞으면 보이는 정렬과 Python의 해석이 어긋나 오류가 생길 수 있습니다."],"code":{"source":"    print(\"안녕\")","kind":"python","output":"","error":"IndentationError","caption":"파일의 첫 줄에 블록을 여는 문장 없이 들여쓰면 IndentationError가 발생합니다."}},{"title":"주석은 설명이고, 문자열 속 #은 글자입니다.","body":["문자열 밖에서 #을 만나면 그 지점부터 해당 줄의 끝까지는 주석입니다. 주석은 사람이 코드를 읽을 때 참고할 설명이며, 아래 예시에서 출력 명령으로 실행되지 않습니다. 줄 하나 전체를 주석으로 쓸 수도 있고, 코드 뒤에 짧은 설명을 붙일 수도 있습니다.","하지만 따옴표 안의 #은 문자열의 내용입니다. print(\"# 시작\")은 # 시작이라는 글자를 보여 줍니다. 코드 파일의 빈 줄은 이 예시의 실행 결과를 바꾸지 않고 덩어리를 읽기 쉽게 나누는 데 쓰입니다. 출력에 빈 줄을 넣고 싶다면 코드의 빈 줄과 구분해야 합니다."],"code":{"source":"# 제목을 표시합니다.\nprint(\"# 시작\")  # 여기부터는 설명입니다.\n\nprint(\"완료\")","kind":"python","output":"# 시작\n완료","error":null,"caption":"문자열 안의 #만 출력됩니다. 주석 두 개와 코드 파일의 빈 줄은 출력 줄을 추가하지 않습니다."}}],"worked":{"question":"이 파일의 설명 글자와 출력되는 글자를 구분하고, 실행 순서를 따라가 봅시다.","code":{"source":"# 간단한 안내\nprint(\"입장\")\nif True:\n    print(\"# 안내\")\n    print(\"환영합니다\")\n\nprint(\"종료\")","kind":"python","output":"입장\n# 안내\n환영합니다\n종료","error":null,"caption":"첫 줄의 주석은 실행하지 않습니다. True 블록의 두 줄을 지나 블록 밖의 마지막 줄로 이어집니다."},"steps":["첫 줄은 문자열 밖의 #으로 시작하는 주석입니다. 첫 출력은 그다음 줄의 입장입니다.","if True:의 블록에는 같은 깊이로 들여쓴 print 두 개가 있습니다. 조건이 참이므로 # 안내, 환영합니다를 순서대로 출력합니다.","마지막 print는 들여쓰기가 끝난 블록 밖의 줄입니다. 코드의 빈 줄은 출력에 추가되지 않고, 마지막으로 종료가 나타납니다."],"answer":"입장, # 안내, 환영합니다, 종료의 네 줄입니다. 실행 순서와 블록 소속, 문자열과 주석의 경계를 각각 확인하면 결과를 읽을 수 있습니다."},"misconception":{"question":"들여쓰기는 보기 좋게 정렬하는 꾸밈인가요?","answer":"Python에서 줄 앞의 들여쓰기는 어떤 블록에 속하는지 나타내는 문법입니다. 같은 블록의 같은 깊이는 맞춰야 합니다. 다만 공백 4칸은 이 강좌가 따르는 스타일 권장입니다. 모든 줄을 4칸 들여쓰는 것이 아니며, 블록 밖의 줄은 왼쪽에서 시작합니다."},"keypoints":["조건이나 반복이 없는 순차 코드에서는 문장이 위에서 아래로 실행됩니다.","들여쓰기는 블록 소속을 나타냅니다. 같은 깊이는 맞추고 이 강좌에서는 공백 4칸을 사용합니다.","문자열 밖의 #은 줄 끝까지의 주석을 시작합니다. 문자열 안의 #은 출력할 글자가 될 수 있습니다."],"examples":[{"question":"아래 파일의 출력 순서를 먼저 예상하고 실행하세요. 이어서 첫째 다음에 둘째가 나오도록 코드 두 줄의 순서만 바꾸어 다시 실행해 보세요.","skill":"실행 순서 추적","solution":{"answer":"원래는 둘째, 첫째 순서입니다. 두 줄의 위치를 바꾸면 첫째, 둘째 순서가 됩니다.","code":{"source":"print(\"첫째\")\nprint(\"둘째\")","kind":"python","output":"첫째\n둘째","error":null,"caption":"두 출력 요청의 위치만 바꾼 코드입니다."}},"explanation":"문자열의 뜻이 실행 순서를 정하지 않습니다. 이 순차 프로그램에서는 위에 적힌 출력 요청부터 실행합니다.","code":"print(\"둘째\")\nprint(\"첫째\")","codeKind":"python"},{"question":"이 예시의 if True: 아래 블록은 실행됩니다. 먼저 어느 출력 명령들이 그 블록에 속하는지 적으세요. 이어서 진행 다음에 확인을 출력하는 줄을 같은 블록 안에 추가하세요. 완료는 블록 밖에 그대로 두고 파일로 실행하세요.","skill":"블록 소속 읽기와 적용","solution":{"answer":"원래 블록 안에는 준비와 진행을 출력하는 두 줄이 있습니다. 확인을 출력하는 새 줄도 공백 4칸으로 맞추면 준비, 진행, 확인, 완료가 차례로 나옵니다.","code":{"source":"if True:\n    print(\"준비\")\n    print(\"진행\")\n    print(\"확인\")\nprint(\"완료\")","kind":"python","output":"준비\n진행\n확인\n완료","error":null}},"explanation":"같은 블록의 같은 깊이는 들여쓰기를 맞춥니다. 완료를 출력하는 줄은 왼쪽으로 돌아와 있으므로 if True:의 블록 밖입니다.","code":"if True:\n    print(\"준비\")\n    print(\"진행\")\nprint(\"완료\")","codeKind":"python"},{"question":"아래 파일은 블록 안의 두 줄을 공백 2칸으로 맞췄습니다. 그대로 실행해 본 뒤, 두 줄을 모두 공백 4칸으로 바꾸어 다시 실행하세요. 결과가 같은지 확인하고, 공백 4칸이 권장 스타일이라는 뜻을 설명해 보세요. if True: 아래 블록은 실행됩니다.","skill":"문법과 스타일 구분","solution":{"answer":"두 경우 모두 A, B, 완료가 차례로 출력됩니다. 공백 4칸은 이 강좌와 Python 스타일 가이드의 권장이며, 2칸은 무조건 문법 오류라는 뜻이 아닙니다.","code":{"source":"if True:\n    print(\"A\")\n    print(\"B\")\nprint(\"완료\")","kind":"python","output":"A\nB\n완료","error":null,"caption":"블록 안의 두 줄을 각각 공백 4칸으로 맞춘 코드입니다."}},"explanation":"문법의 핵심은 블록의 깊이와 같은 깊이의 일관성입니다. 이 문제에서는 블록의 구조를 유지한 채 두 줄의 들여쓰기를 함께 바꿉니다. 마지막 줄은 블록 밖이므로 들여쓰지 않습니다.","code":"if True:\n  print(\"A\")\n  print(\"B\")\nprint(\"완료\")","codeKind":"python"},{"question":"아래 한 줄만 들어 있는 파일은 처음부터 이유 없이 들여써져 있습니다. 안녕을 출력하도록 고치고 파일로 실행하세요. 앞의 공백을 더 넣거나 줄을 주석으로 만드는 방법이 목표에 맞지 않는 이유도 적으세요.","skill":"불필요한 들여쓰기 수정","solution":{"answer":"print 앞의 공백을 지워 왼쪽에서 시작하게 하면 안녕이 출력됩니다.","code":{"source":"print(\"안녕\")","kind":"python","output":"안녕","error":null}},"explanation":"앞에서 블록을 여는 문장이 없으므로 처음부터 들여쓰면 오류가 납니다. 공백을 더 넣어도 해결되지 않으며, 주석으로 바꾸면 필요한 출력이 사라집니다.","code":"    print(\"안녕\")","codeKind":"python"},{"question":"아래 파일의 출력을 예상하고 직접 실행하세요. 이어서 맨 아래에 자신만의 주석 한 줄을 추가하고 다시 실행해 출력이 그대로인지 확인하세요. 따옴표 안팎의 #이 어떻게 다른지도 적으세요.","skill":"주석과 문자 구분","solution":{"answer":"출력은 # 메모 한 줄입니다. 예를 들어 # 다시 확인함을 마지막 줄에 추가해도 출력은 같습니다. 주석 내용은 자유롭게 적어도 됩니다.","code":{"source":"# 제목\nprint(\"# 메모\")  # 화면에 표시\n# 다시 확인함","kind":"python","output":"# 메모","error":null,"caption":"마지막 주석은 자유롭게 바꿀 수 있습니다."}},"explanation":"문자열 밖의 # 뒤는 설명용 주석입니다. 따옴표 안의 #은 문자열의 내용이므로 출력에 포함됩니다. 주석을 추가해도 print 요청 자체는 바뀌지 않습니다.","code":"# 제목\nprint(\"# 메모\")  # 화면에 표시","codeKind":"python"}]},{"id":"python-l005","order":5,"title":"문법 오류와 실행 중 오류","subtitle":"오류 메시지는 틀렸다는 판정이 아니라, 멈춘 이유와 살펴볼 위치를 알려 줍니다.","minutes":9,"goal":"문법 오류와 실행 중 오류를 구분하고, 파일·줄 번호·오류 종류를 근거로 작은 수정을 시도한다.","intro":"코드를 실행했는데 기대한 글자 대신 영어 메시지가 나올 수 있습니다. 이때 메시지를 통째로 외우거나 여러 줄을 한꺼번에 고칠 필요는 없어요. 먼저 실행을 시작하지 못한 것인지, 실행하다가 멈춘 것인지를 나누면 확인할 곳이 줄어듭니다.","sections":[{"title":"문법 오류는 코드를 읽는 단계에서 발견됩니다","body":["파이썬이 코드를 실행하려면 먼저 괄호, 따옴표, 들여쓰기처럼 문장을 이루는 약속을 해석할 수 있어야 합니다. 이 약속에 맞지 않아 읽을 수 없으면 SyntaxError라는 문법 오류가 발생합니다. 예를 들어 여는 괄호를 썼는데 닫는 괄호가 없다면 어디까지 하나의 명령인지 완성되지 않았습니다.","아래 두 줄을 한 .py 파일에 저장해 실행한다고 생각해 보세요. 파이썬은 그 파일의 문법을 먼저 확인하므로, 두 번째 줄에 문법 오류가 있으면 첫 번째 print도 실행되지 않습니다. 이것은 대화형 창에서 앞선 입력을 이미 실행한 뒤 새 입력을 보내는 상황과 다릅니다."],"code":{"source":"print(\"시작\")\nprint(\"끝\"","kind":"python","output":"","error":"SyntaxError","caption":"한 파일로 실행하면 문법 오류 때문에 시작도 출력되지 않습니다."}},{"title":"실행 중 오류는 그 지점에서 흐름을 멈춥니다","body":["문법에 맞는 코드라도 실제 계산이나 동작을 할 수 없는 경우가 있습니다. 0으로 나누는 식은 파이썬 문법으로 읽을 수 있지만 계산할 수 없어서 ZeroDivisionError가 발생합니다. 이런 실행 중 오류를 예외라고 부릅니다.","아래 파일에서는 첫 번째 출력까지 마친 뒤 두 번째 줄의 계산에서 멈춥니다. 이미 출력한 시작은 남고, 마지막의 끝은 출력되지 않습니다. 여기서는 오류를 따로 처리하지 않은 짧은 프로그램을 보고 있습니다. 예외를 처리하며 계속 실행하는 방법은 나중에 배우며, 지금은 어디까지 실행됐는지 읽는 데 집중합니다."],"code":{"source":"print(\"시작\")\nprint(6 / 0)\nprint(\"끝\")","kind":"python","output":"시작","error":"ZeroDivisionError","caption":"시작을 출력한 뒤 0으로 나누는 계산에서 멈춥니다. 오류 메시지는 일반 출력과 구분해 읽습니다."}},{"title":"파일, 줄 번호, 오류 종류를 연결해서 읽습니다","body":["실행 중 오류의 메시지에는 Traceback이라는 안내가 붙을 수 있습니다. 그 아래의 File은 살펴볼 파일을, line 뒤의 수는 줄 번호를 알려 줍니다. 마지막 줄에서는 ZeroDivisionError 같은 오류 종류와 이유를 읽을 수 있습니다. 아래는 앞의 코드를 practice.py에 저장해 실행했을 때 볼 수 있는 메시지의 핵심 부분입니다.","문법 오류에도 파일과 줄 번호, 표시 화살표가 나올 수 있습니다. 표시된 위치는 파이썬이 문제를 알아차린 자리이므로, 반드시 그 글자만 고치면 된다는 뜻은 아닙니다. 앞줄에서 괄호나 따옴표를 닫지 않았는지도 함께 확인하세요. 파이썬 버전과 실행 도구에 따라 화살표와 문구의 모양은 달라질 수 있습니다."],"code":{"source":"Traceback (most recent call last):\n  File \"practice.py\", line 2, in <module>\n    print(6 / 0)\nZeroDivisionError: division by zero","kind":"text","caption":"오류 메시지에서 파일 practice.py, 줄 번호 2, 오류 종류 ZeroDivisionError를 찾습니다. 실행할 코드는 아닙니다."}},{"title":"한 가지 원인을 고치고 같은 파일을 다시 실행합니다","body":["먼저 어떤 결과를 기대했는지 적고, 메시지가 가리킨 위치와 주변 코드를 비교합니다. 닫는 괄호가 빠졌다면 그것을 보충하고, 명령 이름의 철자가 틀렸다면 철자를 바로잡습니다. 한 번에 많은 부분을 바꾸면 어떤 수정이 효과가 있었는지 알기 어려우므로 확인한 원인부터 작게 고칩니다.","수정한 코드를 저장한 다음 같은 파일을 다시 실행합니다. 오류 메시지가 없어졌는지와 원하는 결과가 나왔는지는 따로 확인해야 해요. 문법이 올바르고 오류 없이 끝났더라도 출력 순서나 문구가 의도와 다를 수 있기 때문입니다. 아래처럼 기대한 순서를 미리 정하면 결과를 비교하기 쉬워집니다."],"code":{"source":"print(\"시작\")\nprint(\"확인\")\nprint(\"끝\")","kind":"python","output":"시작\n확인\n끝","error":null,"caption":"오류 없이 끝나는지만 보지 말고, 기대한 세 줄이 이 순서로 나오는지도 확인합니다."}}],"worked":{"question":"준비 다음에 출발을 출력하려고 했는데, 두 번째 줄을 prnit(\"출발\")이라고 썼습니다. 준비만 출력된 뒤 NameError가 나왔다면 무엇을 확인해야 할까요?","code":{"source":"print(\"준비\")\nprint(\"출발\")","kind":"python","output":"준비\n출발","error":null,"caption":"명령 이름의 철자를 print로 바로잡아 저장한 수정본입니다."},"steps":["준비가 출력됐으므로 파일은 실행을 시작했고, 그 뒤의 동작에서 멈췄다는 사실을 확인합니다.","NameError는 찾으려는 이름을 알 수 없을 때 나타납니다. 두 번째 줄의 prnit를 앞에서 사용한 print와 비교하면 철자가 바뀐 것을 찾을 수 있습니다.","prnit를 print로 고친 뒤 저장하고 다시 실행합니다. 메시지가 사라졌는지뿐 아니라 준비와 출발이 차례로 출력되는지도 비교합니다."],"answer":"오류 종류와 실행된 위치를 근거로 철자 한 곳을 수정하면, 두 출력이 의도한 순서대로 실행됩니다."},"misconception":{"question":"오류가 난 줄보다 위의 코드는 언제나 이미 실행됐을까요?","answer":"그렇지 않습니다. 이 레슨처럼 .py 파일 전체에 문법 오류가 있으면 그 파일의 실행을 시작하지 못하므로 위의 print도 실행되지 않습니다. 문법을 통과한 뒤 실행 중 오류로 멈춘 경우에는 그 전에 완료한 출력이 남습니다. 대화형 창에서 이미 실행한 이전 입력은 이후 입력의 문법 오류가 생겨도 지워지지 않습니다."},"keypoints":["문법 오류는 코드를 읽는 단계의 문제이고, 실행 중 오류는 실제 동작 중 생긴 문제입니다.","파일·줄 번호·오류 종류를 함께 읽고, 표시 위치 주변의 괄호·따옴표·철자도 확인합니다.","근거가 있는 부분을 작게 고쳐 저장하고, 오류 유무와 기대한 결과를 각각 확인합니다."],"examples":[{"question":"아래 두 줄을 practice.py 하나의 파일에 저장해 실행하세요. 시작이 출력되는지와 오류 종류를 확인하세요. 빠진 괄호를 보충한 뒤 저장하고 다시 실행해 두 출력이 나타나는지 비교하세요.","skill":"파일의 문법 오류 수정","solution":{"answer":"수정 전에는 SyntaxError가 나고 시작도 출력되지 않습니다. 마지막에 닫는 괄호를 넣으면 시작과 끝이 차례로 출력됩니다.","code":{"source":"print(\"시작\")\nprint(\"끝\")","kind":"python","output":"시작\n끝","error":null}},"explanation":"파일은 실행을 시작하기 전에 문법을 확인합니다. 두 번째 줄에 문법 오류가 있으면 그 파일의 첫 번째 줄도 실행되지 않습니다.","code":"print(\"시작\")\nprint(\"끝\"","codeKind":"python"},{"question":"아래 파일을 실행하기 전에 일반 출력이 어디까지 나올지 적으세요. 실행 후 오류 종류를 확인하고, 두 번째 줄을 print(\"계산 확인\")으로 바꾸어 다시 실행하세요. 변경 전과 후의 결과를 비교해 보세요.","skill":"실행 중 오류와 이전 출력","solution":{"answer":"원래 파일은 A를 출력한 뒤 ZeroDivisionError로 멈춥니다. 두 번째 줄을 바꾸면 A, 계산 확인, B가 차례로 출력됩니다.","code":{"source":"print(\"A\")\nprint(\"계산 확인\")\nprint(\"B\")","kind":"python","output":"A\n계산 확인\nB","error":null}},"explanation":"0으로 나누는 식은 문법상 읽을 수 있지만 실행할 수 없습니다. 처리하지 않은 오류가 생기기 전의 출력은 남고 그 뒤의 줄은 실행되지 않습니다.","code":"print(\"A\")\nprint(6 / 0)\nprint(\"B\")","codeKind":"python"},{"question":"아래 코드를 practice.py에 저장하고 실행하세요. 오류 메시지에서 파일 이름, 줄 번호, 오류 종류를 찾아 적으세요. 철자가 다른 곳 한 군데를 고친 뒤 준비와 출발이 차례로 출력되는지 확인하세요.","skill":"오류 위치와 이름 확인","solution":{"answer":"확인할 파일은 practice.py, 줄 번호는 2, 오류 종류는 NameError입니다. prnit를 print로 고치면 준비 다음에 출발이 출력됩니다.","code":{"source":"print(\"준비\")\nprint(\"출발\")","kind":"python","output":"준비\n출발","error":null}},"explanation":"파이썬이 prnit라는 이름을 찾지 못해 멈춥니다. 메시지가 가리킨 줄을 앞의 print와 비교하면 철자가 뒤바뀐 것을 확인할 수 있습니다. 수정 후에는 저장하고 같은 파일을 다시 실행합니다.","code":"print(\"준비\")\nprnit(\"출발\")","codeKind":"python"},{"question":"아래 코드로 Ready라는 글자를 출력하려고 합니다. 따옴표와 괄호의 짝을 확인해 필요한 부분만 고친 뒤 실행하세요. 무엇이 빠져 있었는지도 설명하세요.","skill":"작은 문법 수정","solution":{"answer":"Ready 뒤의 닫는 큰따옴표가 빠졌습니다. 괄호 앞에 큰따옴표를 넣으면 Ready가 출력됩니다.","code":{"source":"print(\"Ready\")","kind":"python","output":"Ready","error":null}},"explanation":"문자열의 끝을 표시하는 따옴표와 print의 괄호는 각각 필요합니다. 오류 메시지가 없어진 것과 원하는 글자가 출력되는 것을 함께 확인합니다.","code":"print(\"Ready)","codeKind":"python"},{"question":"파이썬 대화형 창에서 아래 기록처럼 한 줄씩 입력하세요. >>>는 직접 입력하지 않습니다. A가 나온 뒤 두 번째 입력에 오류가 나도 A가 남는지 확인하세요. 이어서 두 번째 입력의 괄호를 고쳐 B를 출력해 보세요. 두 줄을 하나의 파일로 실행하는 실습과 구분하세요.","skill":"파일과 대화형의 차이","solution":{"answer":"A는 이미 실행된 이전 입력의 출력이므로 남습니다. 두 번째 입력에는 닫는 괄호가 하나 더 있어 SyntaxError가 납니다. print(\"B\")를 새로 입력하면 B가 추가로 출력됩니다.","code":{"source":"print(\"B\")","kind":"python","output":"B","error":null,"caption":"오류가 난 대화형 창에 새로 입력할 코드입니다. 앞서 나온 A는 그대로 남습니다."}},"explanation":"대화형 창의 이전 입력과 새 입력은 구분됩니다. 새 입력의 문법 오류가 이미 끝낸 출력을 되돌리지 않습니다. 하나의 파일 전체에 문법 오류가 있어 실행을 시작하지 못하는 경우와 다릅니다.","code":">>> print(\"A\")\nA\n>>> print(\"B\"))","codeKind":"console","codeLabel":"대화형 창에서 순서대로 입력할 기록"}]}],"review":[{"question":"3과 4를 더한 값을 화면에 출력하는 한 줄 프로그램을 직접 작성하고 실행하세요. 이 프로그램의 입력 자료, 처리, 출력을 각각 한 문장으로 설명해 보세요.","skill":"실행 흐름 · 입력과 결과","solution":{"answer":"예시 답: 입력 자료는 코드에 적힌 3과 4이고, 처리는 두 수를 더하는 계산입니다. 출력은 화면에 나타나는 7입니다.","code":{"source":"print(3 + 4)","kind":"python","output":"7","error":null,"caption":"숫자 7을 코드에 바로 적는 대신, 덧셈의 결과를 출력하는 예시입니다."}},"explanation":"프로그램에 적어 둔 값도 처리할 자료가 될 수 있으므로 키보드로 값을 물어보는 단계가 꼭 필요한 것은 아닙니다. 먼저 3 + 4를 계산하고 print가 그 결과를 화면에 보여 줍니다.","related":["python-l001","python-l003"]},{"question":"아래 코드를 실행하기 전에 화면에 나올 내용을 줄 순서대로 적어 보세요. 그다음 직접 타이핑하여 한 파일로 실행하고, 주석이 출력에 포함되는지 확인하세요.","code":"print(\"준비\")\n# 다음에는 시작을 알립니다.\nprint(\"시작\")\nprint(\"완료\")","codeKind":"python","codeLabel":"실행 순서를 예측할 코드","skill":"실행 흐름 · 순서와 주석","solution":{"answer":"예시 답: 준비, 시작, 완료가 각각 한 줄씩 이 순서로 출력됩니다. 두 번째 줄의 주석은 출력되지 않습니다.","code":{"source":"print(\"준비\")\n# 다음에는 시작을 알립니다.\nprint(\"시작\")\nprint(\"완료\")","kind":"python","output":"준비\n시작\n완료","error":null,"caption":"예측한 세 줄과 실제 실행 결과를 비교하세요."}},"explanation":"이 순차 프로그램은 위에서 아래로 출력 명령을 실행합니다. 따옴표 밖의 #로 시작한 주석은 코드를 읽는 사람을 위한 설명이므로 출력 명령처럼 실행하지 않습니다.","related":["python-l001","python-l004"]},{"question":"아래 코드를 한 파일로 실행하면 어디까지 출력될지 먼저 적어 보세요. 직접 실행한 뒤, 멈춘 줄과 오류 종류를 확인하고 마지막 단계가 출력되지 않는 이유를 설명하세요.","code":"print(\"첫 단계\")\nprint(8 / 0)\nprint(\"마지막 단계\")","codeKind":"python","codeLabel":"실행 중 오류가 있는 코드","skill":"실행 흐름 · 오류 이후의 동작","solution":{"answer":"예시 답: 첫 단계만 출력됩니다. 두 번째 줄에서 0으로 나누려 하여 ZeroDivisionError가 발생하고, 세 번째 줄은 실행하지 못합니다.","code":{"source":"print(\"첫 단계\")\nprint(8 / 0)\nprint(\"마지막 단계\")","kind":"python","output":"첫 단계","error":"ZeroDivisionError","caption":"수정본이 아니라, 오류 전에 남는 출력을 확인하는 코드입니다."}},"explanation":"이 파일은 문법을 읽는 단계는 통과하지만 두 번째 줄을 계산하는 도중 오류가 납니다. 앞에서 완료한 출력은 남고, 여기서는 오류를 따로 처리하지 않으므로 뒤의 명령으로 넘어가지 못합니다.","related":["python-l004","python-l005"]},{"question":"아래 코드가 출력할 내용을 #과 공백까지 포함해 적은 뒤 직접 실행하세요. 두 개의 # 중 어느 것이 문자열의 글자이고 어느 것이 주석의 시작인지 설명해 보세요.","code":"print(\"# 안내\")  # 화면에 안내를 표시합니다.","codeKind":"python","codeLabel":"문자열과 주석을 구별할 코드","skill":"코드 읽기 · 문자열과 주석","solution":{"answer":"예시 답: # 뒤에 공백 한 칸을 두고 안내가 출력됩니다. 따옴표 안의 첫 번째 #은 글자이고, 닫는 괄호 뒤의 두 번째 #이 주석을 시작합니다.","code":{"source":"print(\"# 안내\")  # 화면에 안내를 표시합니다.","kind":"python","output":"# 안내","error":null,"caption":"문자열 경계를 표시하는 따옴표는 출력에 포함되지 않습니다."}},"explanation":"같은 #이라도 코드에서 놓인 위치에 따라 역할이 달라집니다. 따옴표 안은 문자열의 내용이며, 따옴표 밖의 #부터 줄 끝까지는 설명인 주석입니다.","related":["python-l003","python-l004"]},{"question":"아래는 대화형 창의 실행 기록입니다. 이 기록에서 실행할 코드만 골라 hello.py에 직접 작성하고 저장한 뒤 파일로 실행하세요. 두 줄의 출력이 원래 기록과 같은지 확인해 보세요.","code":">>> print(\"안녕\")\n안녕\n>>> print(2 + 5)\n7","codeKind":"console","codeLabel":"대화형 창의 기록 — 코드 파일에 그대로 옮기지 마세요","skill":"코드 읽기 · 입력 표시와 코드 파일","solution":{"answer":"예시 답: hello.py에는 두 개의 print 명령만 저장합니다. >>> 표시와 그 아래에 나온 실행 결과는 파일 내용에 넣지 않습니다.","code":{"source":"print(\"안녕\")\nprint(2 + 5)","kind":"python","output":"안녕\n7","error":null,"caption":"이 두 줄을 hello.py의 내용으로 작성해 실행할 수 있습니다."}},"explanation":">>>는 대화형 창이 입력을 기다린다는 표시이고, 안녕과 7은 실행 결과입니다. 코드 파일에는 파이썬이 실행할 명령을 적으며, 저장한 두 명령을 실행하면 같은 순서의 결과를 얻습니다.","related":["python-l002","python-l003"]},{"question":"아래에서 if True: 아래의 블록은 실행되는 것으로 주어졌습니다. 그 블록 안에 속한 print가 어느 줄인지 적고, 세 print의 출력 순서를 예측하세요. 들여쓰기를 그대로 타이핑하여 결과를 확인해 보세요.","code":"print(\"밖의 첫 줄\")\nif True:\n    print(\"안쪽\")\nprint(\"밖의 마지막 줄\")","codeKind":"python","codeLabel":"블록의 범위를 읽을 코드","skill":"코드 읽기 · 블록의 범위","solution":{"answer":"예시 답: 세 번째 줄의 들여쓴 print(\"안쪽\")만 해당 블록 안에 속합니다. 출력 순서는 밖의 첫 줄, 안쪽, 밖의 마지막 줄입니다.","code":{"source":"print(\"밖의 첫 줄\")\nif True:\n    print(\"안쪽\")\nprint(\"밖의 마지막 줄\")","kind":"python","output":"밖의 첫 줄\n안쪽\n밖의 마지막 줄","error":null,"caption":"안쪽 줄은 공백 네 칸으로 들여썼고, 마지막 줄은 들여쓰기를 되돌렸습니다."}},"explanation":"들여쓰기는 명령이 어느 블록에 속하는지 나타냅니다. 마지막 print는 들여쓰기를 되돌렸으므로 블록 밖입니다. 여기서는 주어진 블록이 실행되므로 세 출력 명령 모두 위에서 아래 순서로 실행됩니다.","related":["python-l004"]},{"question":"아래 내용을 practice.py에 저장하여 실행하세요. 오류 메시지에서 파일 이름, 줄 번호, 오류 종류를 찾아 적고, 그 줄의 어떤 철자를 먼저 확인해야 하는지 설명해 보세요.","code":"print(\"점검 시작\")\n# 다음 줄에서 점검 완료를 알립니다.\nprnit(\"점검 완료\")","codeKind":"python","codeLabel":"오류 위치를 찾을 코드","skill":"오류 위치 · 줄 번호와 종류","solution":{"answer":"예시 답: 파일은 practice.py, 위치는 3번째 줄, 오류 종류는 NameError입니다. 세 번째 줄의 prnit가 배운 명령 이름인 print와 같은 철자인지 확인합니다.","code":{"source":"print(\"점검 시작\")\n# 다음 줄에서 점검 완료를 알립니다.\nprnit(\"점검 완료\")","kind":"python","output":"점검 시작","error":"NameError","caption":"오류 위치를 확인하는 원본입니다. 파일 경로와 메시지의 자세한 모양은 환경에 따라 다를 수 있습니다."}},"explanation":"파일과 줄 번호는 살펴볼 위치를 알려 주며 주석도 파일의 한 줄로 셉니다. NameError는 찾으려는 이름을 알 수 없다는 뜻입니다. 이 코드에서는 print의 철자를 prnit로 잘못 적은 것이 원인입니다.","related":["python-l004","python-l005"]},{"question":"아래 두 줄 전체를 한 .py 파일에 작성하세요. 준비가 출력될지 먼저 예측한 뒤 파일로 실행하고, 오류 종류와 빠진 기호가 있는 줄을 찾아 적으세요. 대화형 창에 한 줄씩 입력했을 때와 혼동하지 마세요.","code":"print(\"준비\")\nprint(\"출발\"","codeKind":"python","codeLabel":"파일 전체의 문법을 확인할 코드","skill":"오류 위치 · 파일의 문법 검사","solution":{"answer":"예시 답: 준비도 출력되지 않습니다. 두 번째 줄에 닫는 괄호 )가 빠져 있어 SyntaxError가 발생합니다.","code":{"source":"print(\"준비\")\nprint(\"출발\"","kind":"python","output":"","error":"SyntaxError","caption":"한 파일로 실행하면 첫 번째 출력도 시작되지 않는 것을 확인하는 코드입니다."}},"explanation":"파일을 실행하기 전에 전체 문법을 읽는 단계에서 닫히지 않은 괄호를 발견합니다. 따라서 첫 번째 명령도 실행되지 않습니다. 실행 중 오류 전에 완료한 출력이 남는 3번 문제와 이 점이 다릅니다.","related":["python-l002","python-l005"]},{"question":"아래 코드는 Start 다음 줄에 End를 출력하려는 프로그램입니다. 두 출력 명령을 모두 유지하고 순서도 바꾸지 않은 채, 빠진 기호를 넣어 수정하세요. 저장하고 실행하여 두 줄의 출력을 확인해 보세요.","code":"print(\"Start\")\nprint(\"End)","codeKind":"python","codeLabel":"수정할 코드","skill":"작은 수정 · 의도를 유지하며 고치기","solution":{"answer":"예시 답: 두 번째 줄의 End 뒤에 닫는 따옴표를 넣습니다. 실행 결과가 Start, End 두 줄인지 확인합니다.","code":{"source":"print(\"Start\")\nprint(\"End\")","kind":"python","output":"Start\nEnd","error":null,"caption":"빠진 따옴표를 넣어 의도한 두 출력을 유지한 수정 예시입니다."}},"explanation":"문자열을 나타내는 따옴표는 여는 것과 닫는 것이 짝을 이루어야 합니다. 오류가 난 줄을 지우면 End가 사라지므로 원래 목표를 이루지 못합니다. 오류가 없어졌는지와 원하는 결과가 나오는지를 함께 확인하세요.","related":["python-l003","python-l004","python-l005"]},{"question":"작업용 hello.py에 아래 코드를 작성하고 저장하여 실행하세요. 그다음 출력할 글자를 수정으로 바꾸고 다시 저장하여 같은 파일을 실행하세요. 여전히 처음이 나온다면 무엇을 확인할지 두 가지를 적어 보세요.","code":"print(\"처음\")","codeKind":"python","codeLabel":"먼저 저장하여 실행할 코드","skill":"작은 수정 · 저장과 재실행","solution":{"answer":"예시 답: print(\"수정\")으로 바꾸고 저장한 뒤 같은 hello.py를 다시 실행합니다. 결과가 바뀌지 않으면 편집한 내용을 저장했는지, 실행한 파일의 위치와 이름이 편집 중인 파일과 같은지 확인합니다.","code":{"source":"print(\"수정\")","kind":"python","output":"수정","error":null,"caption":"수정 후 저장할 파일의 내용과 다시 실행했을 때의 예상 결과입니다."}},"explanation":"파일 실행은 편집기에 보이는 저장 전 내용이 아니라 저장된 파일 내용을 기준으로 합니다. 오류 메시지가 없더라도 예전 파일이나 다른 위치의 파일을 실행했을 수 있으므로 코드와 실행 대상을 함께 확인해야 합니다.","related":["python-l002","python-l005"]}]},{"id":"python-ch02","slug":"ch02","number":2,"title":"값·이름·연산","description":"값에 이름을 붙이고, 알맞은 연산과 변환을 골라 입력을 결과로 연결합니다.","prerequisite":"선행 학습: 챕터 1 · 프로그램을 읽고 실행하기","runtime":"Python 3","testedVersion":"3.12.14","lessons":[{"id":"python-l006","order":1,"title":"변수는 값에 붙이는 이름","subtitle":"이름이 지금 가리키는 값을 따라가면, 값이 바뀌는 코드가 읽힙니다.","minutes":10,"goal":"대입의 오른쪽을 먼저 계산한 뒤 이름에 연결하고, 재대입 전후에 각 이름이 가리키는 값을 설명한다.","intro":"앞 챕터에서는 print 안에 숫자와 글자를 바로 적었습니다. 그런데 같은 가격을 여러 곳에서 사용하거나 계산한 결과를 다음 줄에서 다시 쓰려면, 매번 값을 새로 적는 일이 불편해집니다. 값에 의미 있는 이름을 붙이면 무엇을 다루는지 드러나고, 그 이름으로 현재 값을 다시 사용할 수 있습니다.","sections":[{"title":"이름을 붙이면 값의 역할이 보입니다.","body":["price = 1200은 숫자 1200에 price라는 이름을 연결하는 대입입니다. 이처럼 값에 연결해 사용하는 이름을 변수라고 부릅니다. price라는 철자가 원래부터 가격을 계산하는 기능을 가진 것은 아닙니다. 사람이 코드의 뜻을 읽기 좋도록 붙인 이름입니다.","그다음 줄에서 price를 쓰면 그 이름에 연결된 현재 값을 사용합니다. print(price)는 1200을 출력하지만, print(\"price\")는 따옴표 안의 글자를 출력합니다. 앞 챕터에서 배운 문자열의 경계가 이름과 문자 값을 구분할 때도 중요합니다."],"code":{"source":"price = 1200\nprint(price)\nprint(\"price\")","kind":"python","output":"1200\nprice","error":null,"caption":"대입은 이름과 값을 연결합니다. 대입문 자체가 값을 화면에 출력하지는 않습니다."}},{"title":"대입은 오른쪽 값을 먼저 구한 뒤 연결합니다.","body":["count = count + 1을 수학의 등식으로 읽으면 같은 수가 자신보다 1 커야 하므로 이상해 보입니다. 하지만 파이썬의 =는 양쪽이 같다고 주장하는 기호가 아닙니다. 오른쪽의 값을 구한 뒤 왼쪽 이름이 그 값을 가리키도록 하는 동작입니다.","아래에서는 count가 먼저 2에 연결되어 있습니다. 두 번째 대입의 오른쪽 count + 1은 현재 값 2를 사용하여 3이 됩니다. 그 계산이 끝난 뒤 count를 3에 다시 연결합니다. 같은 이름에 다시 대입하는 일을 재대입이라고 하며, 이후의 count는 새 값을 사용합니다."],"code":{"source":"count = 2\nprint(count)\ncount = count + 1\nprint(count)","kind":"python","output":"2\n3","error":null,"caption":"오른쪽에서 이전 값 2를 읽고, 계산 결과 3을 왼쪽 이름에 다시 연결합니다."}},{"title":"다른 이름에 대입해도 두 이름이 계속 함께 바뀌지는 않습니다.","body":["saved_price = price는 price라는 이름 자체를 saved_price에 묶는 명령이 아닙니다. 그 시점에 price가 가리키는 값을 구하고, saved_price도 그 값에 연결합니다. 아래에서는 두 이름이 모두 숫자 1000을 가리키는 순간이 생깁니다.","이후 price = 1200을 실행하면 price가 가리키는 값만 달라집니다. 이미 있던 숫자 1000 자체를 1200으로 고치는 것이 아니므로 saved_price는 여전히 1000을 가리킵니다. 지금 다루는 숫자의 재대입에서는 이름마다 현재 연결을 따로 따라가면 됩니다.","계산 결과를 대입할 때도 같습니다. total = price + 500은 그 순간의 덧셈 결과에 total을 연결합니다. 계산 공식을 계속 보관하며 price를 감시하는 기능이 아니므로, 나중에 price가 바뀌었을 때 새 합계가 필요하면 다시 계산해야 합니다."],"code":{"source":"price = 1000\nsaved_price = price\nprice = 1200\nprint(price)\nprint(saved_price)","kind":"python","output":"1200\n1000","error":null,"caption":"price를 새 숫자에 연결해도 saved_price의 기존 연결은 남아 있습니다."}},{"title":"이름은 사용하기 전에 연결하고, 뜻이 드러나게 적습니다.","body":["파이썬이 이름의 현재 값을 찾으려면 그 이름에 먼저 값이 연결되어 있어야 합니다. 아래 파일은 total_price를 출력하는 줄이 대입보다 앞에 있습니다. 이 파일을 새로 실행하면 첫 줄에서 NameError가 나고 다음 대입까지 진행하지 못합니다. 대화형 창에서 예전에 만든 이름이 남아 있는 상황과 새 파일 실행을 구분하세요.","이 과정에서는 영문 소문자와 숫자, 밑줄을 사용해 total_price처럼 이름을 적습니다. 숫자로 시작하거나 이름 중간에 공백을 넣을 수 없으며, if처럼 문법에 이미 쓰이는 단어는 변수 이름으로 사용할 수 없습니다. price와 Price는 서로 다른 이름이므로 철자와 대소문자도 맞춰야 합니다.","의미를 알 수 있는 이름은 메모 역할도 합니다. a보다 total_price가 계산값의 쓰임을 드러냅니다. 이미 출력에 쓰는 print 같은 이름을 다른 값에 대입하면 원래 기능을 쓰기 어려워지므로 새 변수 이름으로 덮어쓰지 않습니다."],"code":{"source":"print(total_price)\ntotal_price = 1200","kind":"python","output":"","error":"NameError","caption":"먼저 이름을 사용한 뒤 나중에 대입해도 첫 줄의 오류가 해결되지는 않습니다. 대입 줄을 위로 옮겨야 합니다."}}],"worked":{"question":"기본 요금에 500을 더해 합계를 구한 뒤 기본 요금이 달라졌습니다. 아래 두 출력이 왜 다른지, 각 대입이 실행되는 시점의 값을 따라가 보세요.","code":{"source":"base_price = 1000\ntotal = base_price + 500\nbase_price = 1200\nprint(total)\ntotal = base_price + 500\nprint(total)","kind":"python","output":"1500\n1700","error":null,"caption":"계산한 값을 보관하는 것과 현재 값을 사용해 다시 계산하는 것을 비교합니다."},"steps":["base_price가 1000일 때 첫 덧셈을 계산하므로 total은 1500에 연결됩니다.","base_price를 1200에 다시 연결해도 total의 기존 값은 1500입니다. 첫 print가 그 값을 보여 줍니다.","두 번째 total 대입에서 현재 base_price인 1200을 읽고 500을 더합니다. 이제 total이 1700에 연결되어 두 번째 출력이 달라집니다."],"answer":"출력은 1500과 1700입니다. total은 계산식을 자동으로 다시 계산하는 이름이 아니라, 대입할 때 구한 값에 연결되는 이름입니다."},"misconception":{"question":"b = a를 한 뒤 a를 바꾸면 b도 자동으로 바뀌나요?","answer":"숫자에 연결된 a를 다른 숫자로 재대입해도 b의 연결은 자동으로 바뀌지 않습니다. b = a는 그때 a가 가리키던 값에 b를 연결합니다. 여기서는 숫자 값 자체의 변경과 이름의 재연결을 구분하는 것이 핵심입니다. 나중에 리스트처럼 내용을 바꿀 수 있는 값을 배울 때는 같은 값을 함께 사용하는 상황을 따로 살펴봅니다."},"keypoints":["변수는 값에 붙이는 이름입니다. 따옴표 없는 이름은 현재 값을 읽고, 따옴표 안의 이름 모양은 문자 값입니다.","대입은 오른쪽 값을 먼저 구한 뒤 왼쪽 이름에 연결합니다. 재대입한 뒤에는 새 값을 읽습니다.","다른 이름의 재대입이나 원래 재료의 변경이 이미 계산한 숫자를 자동으로 갱신하지는 않습니다."],"examples":[{"question":"book_price에 800을 대입하고, 다음 두 줄에 그 값과 book_price라는 글자를 각각 출력하세요. 파일을 실행해 두 출력이 왜 다른지도 설명해 보세요.","skill":"이름과 문자 값 구분","solution":{"answer":"첫 줄에는 800, 둘째 줄에는 book_price가 나타납니다.","code":{"source":"book_price = 800\nprint(book_price)\nprint(\"book_price\")","kind":"python","output":"800\nbook_price","error":null}},"explanation":"따옴표 없는 book_price는 연결된 값 800을 읽습니다. 따옴표로 감싼 표현은 이름을 찾지 않고 그 글자 자체를 사용합니다."},{"question":"아래 코드를 직접 입력하고, 실행 전에 두 번째 대입의 오른쪽과 실행 후 count의 값을 적어 보세요. 이어서 실행해 예상과 비교하세요.","skill":"이전 값으로 재대입","solution":{"answer":"오른쪽 count + 2는 4 + 2이므로 6입니다. 계산한 뒤 count가 6에 연결되어 6을 출력합니다.","code":{"source":"count = 4\ncount = count + 2\nprint(count)","kind":"python","output":"6","error":null}},"explanation":"왼쪽 이름을 먼저 지우는 것이 아닙니다. 오른쪽에서 현재 값을 읽어 계산한 다음, 왼쪽 이름이 계산 결과를 가리키도록 합니다.","code":"count = 4\ncount = count + 2\nprint(count)","codeKind":"python"},{"question":"아래 파일의 두 출력을 먼저 적어 보고 실행하세요. price를 1100에 다시 대입해도 saved_price가 어떻게 되는지 자신의 말로 설명하세요.","skill":"두 이름의 현재 값 추적","solution":{"answer":"saved_price는 900, price는 1100을 출력합니다.","code":{"source":"price = 900\nsaved_price = price\nprice = 1100\nprint(saved_price)\nprint(price)","kind":"python","output":"900\n1100","error":null}},"explanation":"saved_price에는 대입 당시의 값 900이 연결되어 있습니다. price라는 이름에 대한 재대입은 saved_price의 연결을 바꾸지 않습니다.","code":"price = 900\nsaved_price = price\nprice = 1100\nprint(saved_price)\nprint(price)","codeKind":"python"},{"question":"아래 파일을 새로 실행하면 이름을 찾지 못하는 오류가 납니다. 두 줄의 순서만 바꾸어 20을 출력하게 고치고, 왜 대입이 먼저 필요한지 설명하세요.","skill":"이름을 사용하기 전 대입","solution":{"answer":"points = 20을 먼저 실행하고 print(points)를 실행하면 20이 출력됩니다.","code":{"source":"points = 20\nprint(points)","kind":"python","output":"20","error":null}},"explanation":"기존 파일은 아직 points에 값이 연결되지 않은 상태에서 그 이름을 읽으려 합니다. 출력할 시점에 값을 찾을 수 있도록 대입이 앞에 있어야 합니다.","code":"print(points)\npoints = 20","codeKind":"python"},{"question":"아래 코드는 기본값을 1400으로 바꾼 뒤에도 이전 합계를 출력합니다. base를 바꾼 다음 total을 다시 계산하는 한 줄을 추가하여 1600을 출력하세요. 숫자 1600을 print에 직접 적지 마세요.","skill":"계산 결과 다시 구하기","solution":{"answer":"base = 1400 다음에 total = base + 200을 추가하면 현재 기본값으로 합계를 다시 계산합니다.","code":{"source":"base = 1000\ntotal = base + 200\nbase = 1400\ntotal = base + 200\nprint(total)","kind":"python","output":"1600","error":null}},"explanation":"원래 total의 값은 1200입니다. base에 새 값을 대입하는 일과 total을 다시 계산하는 일은 별개이므로, 새 합계가 필요할 때 계산을 다시 실행합니다.","code":"base = 1000\ntotal = base + 200\nbase = 1400\nprint(total)","codeKind":"python"}]},{"id":"python-l007","order":2,"title":"정수와 실수의 계산","subtitle":"원하는 결과가 전체 몫인지, 묶음 수인지, 남은 양인지에 따라 연산을 고릅니다.","minutes":12,"goal":"정수와 실수의 기본 연산, 나눗셈의 세 종류, 괄호와 우선순위에 따른 결과를 설명한다.","intro":"이제 계산할 값에 이름을 붙일 수 있습니다. 다음으로 중요한 일은 원하는 계산을 정확히 고르는 것입니다. 사탕을 똑같이 나눌 때 한 사람의 양을 알고 싶은지, 완성되는 묶음 수를 알고 싶은지, 남는 사탕 수를 알고 싶은지에 따라 필요한 연산이 달라집니다.","sections":[{"title":"정수와 실수는 숫자를 다루는 방식이 다릅니다.","body":["7, 0, -3처럼 정수를 나타내는 값은 int형입니다. 7.0, 0.5처럼 소수점을 사용해 적는 수는 float형으로, 실수의 계산에 사용합니다. 자료형은 값이 어떤 종류이고 어떤 규칙으로 다뤄지는지 구분하는 기준입니다. 7과 7.0은 같은 크기를 나타내지만 서로 같은 종류의 값은 아닙니다.","기본 덧셈은 +, 뺄셈은 -, 곱셈은 *를 사용합니다. 파이썬 코드에서는 곱하기를 수학의 × 대신 *로 적습니다. 정수끼리 이 연산들을 하면 정수 결과를 얻으며, 아래의 7 + 0.5처럼 float가 함께 들어간 계산에서는 float 결과를 얻습니다.","앞 레슨의 대입을 함께 사용해도 계산 원리는 같습니다. price * count는 각 이름의 현재 값을 읽어 곱합니다. 단위를 Python이 자동으로 알아내지는 않으므로, 무엇을 계산한 숫자인지는 이름과 설명으로 드러내야 합니다."],"code":{"source":"print(7)\nprint(7.0)\nprice = 1200\ncount = 3\nprint(price * count)\nprint(7 + 0.5)","kind":"python","output":"7\n7.0\n3600\n7.5","error":null,"caption":"정수 7과 float 7.0의 표기를 비교하고, 이름에 연결된 값으로 계산합니다."}},{"title":"나눗셈은 전체 몫, 내린 몫, 나머지를 나누어 생각합니다.","body":["17을 5로 나눈 값 전체가 필요하면 /를 사용하여 3.4를 얻습니다. /는 정수끼리 계산해 나누어떨어지더라도 float 결과를 만듭니다. 따라서 10 / 5의 결과는 2.0입니다.","17개를 5개씩 완전한 묶음으로 나눌 때는 17 // 5로 묶음 수 3을 구하고, 17 % 5로 남은 수 2를 구할 수 있습니다. //는 나눈 값을 그 값보다 크지 않은 가장 가까운 정수 방향으로 내리는 연산이며, %는 그 몫과 맞는 나머지를 구하는 연산입니다. 여기서는 정수끼리 계산하므로 결과도 정수입니다.","음수에서는 ‘소수점 아래를 그냥 지운다’고 생각하면 틀립니다. -7 / 3은 약 -2.333이므로 아래쪽 정수로 내리면 -3입니다. 따라서 -7 // 3은 -3, -7 % 3은 2입니다. -3에 3을 곱한 -9에 나머지 2를 더하면 원래 수 -7로 돌아옵니다.","정수 a와 0이 아닌 정수 b에서는 a가 (a // b) * b + a % b와 같아집니다. 나머지는 0이 아니면 나누는 수 b와 같은 부호를 가집니다. 나누는 수가 0이면 /, //, % 모두 계산할 수 없으며 앞 챕터에서 본 ZeroDivisionError가 납니다."],"code":{"source":"print(17 / 5)\nprint(17 // 5)\nprint(17 % 5)\nprint(-7 // 3)\nprint(-7 % 3)","kind":"python","output":"3.4\n3\n2\n-3\n2","error":null,"caption":"양수 묶음의 뜻으로 이해한 뒤, 음수에서는 아래쪽 정수로 내리는 규칙을 확인합니다."}},{"title":"괄호는 먼저 계산할 범위를 분명히 보여 줍니다.","body":["파이썬은 식에 적힌 모든 연산을 무조건 왼쪽부터 처리하지 않습니다. **는 거듭제곱으로, 2 ** 3은 2를 세 번 곱한 8입니다. 기본적으로 거듭제곱을 곱셈·나눗셈보다 먼저, 곱셈·나눗셈을 덧셈·뺄셈보다 먼저 계산합니다. 같은 단계의 +와 -끼리, 또는 *와 /·//·%끼리는 왼쪽에서 오른쪽으로 계산합니다.","2 + 3 * 4에서는 3 * 4를 먼저 계산하므로 결과는 14입니다. 두 수를 먼저 더하고 싶다면 (2 + 3) * 4처럼 괄호로 묶어 20을 만듭니다. 괄호는 우선순위를 외우지 못한 표시가 아니라, 계산할 의미를 읽는 사람에게 드러내는 도구이기도 합니다.","음수의 거듭제곱은 밑이 어디까지인지 확인해야 합니다. -2 ** 2는 2 ** 2를 먼저 계산한 뒤 앞의 음수 부호를 적용하여 -4가 됩니다. (-2) ** 2는 음수 -2 전체를 밑으로 하므로 4입니다. 이처럼 헷갈리는 식은 괄호로 의도를 적는 편이 좋습니다."],"code":{"source":"print(2 ** 3)\nprint(2 + 3 * 4)\nprint((2 + 3) * 4)\nprint(-2 ** 2)\nprint((-2) ** 2)","kind":"python","output":"8\n14\n20\n-4\n4","error":null,"caption":"괄호가 어떤 계산을 묶는지 먼저 찾고, 그다음 남은 연산을 읽습니다."}},{"title":"float는 일부 소수를 가까운 값으로 표현합니다.","body":["수학에서 0.1 + 0.2는 0.3입니다. 그런데 Python의 일반적인 float는 수를 내부에서 2진 방식의 제한된 자릿수로 저장합니다. 0.1과 0.2처럼 그 방식으로 정확히 표현할 수 없는 값은 가까운 값으로 저장되므로, 계산 결과에 작은 차이가 드러날 수 있습니다.","아래 첫 출력의 긴 끝자리는 코드의 덧셈 순서가 잘못된 것이 아닙니다. 반면 0.5와 0.25처럼 정확히 표현되는 값도 있으므로 모든 소수 계산에서 눈에 보이는 차이가 생기는 것은 아닙니다. 여기서는 float가 수학의 모든 실수를 무한한 정확도로 저장하지 않는다는 경계만 기억하면 됩니다.","물건 개수나 원 단위 금액처럼 정수로 다룰 수 있는 데이터는 정수로 계산하면 이런 소수 표현 문제를 피할 수 있습니다. 소수의 정밀한 비교·반올림 방식은 그 기능이 필요한 단계에서 배우고, 지금은 출력 끝자리를 보며 곧바로 문법 오류라고 판단하지 않습니다."],"code":{"source":"print(0.1 + 0.2)\nprint(0.5 + 0.25)","kind":"python","output":"0.30000000000000004\n0.75","error":null,"caption":"float의 작은 표현 차이와 정확히 표현되는 소수를 함께 관찰합니다."}}],"worked":{"question":"연필 23자루를 5자루씩 봉투에 넣습니다. 완성되는 봉투 수와 남은 연필 수를 구하고, 두 결과로 원래 연필 수를 다시 확인해 보세요.","code":{"source":"pencils = 23\nbag_size = 5\nfull_bags = pencils // bag_size\nleftover = pencils % bag_size\nprint(full_bags)\nprint(leftover)\nprint(full_bags * bag_size + leftover)","kind":"python","output":"4\n3\n23","error":null,"caption":"완성된 묶음 수와 남은 양을 구한 뒤, 다시 합쳐 원래 개수를 확인합니다."},"steps":["pencils와 bag_size는 개수를 나타내는 정수입니다. 23개 중 5개짜리 완전한 묶음은 4개이므로 //로 full_bags를 구합니다.","완전한 묶음에 넣고 남은 연필은 3자루입니다. %로 이 나머지를 구하여 leftover에 연결합니다.","봉투 4개에 든 4 * 5 = 20자루와 남은 3자루를 합치면 23입니다. 곱셈이 덧셈보다 먼저 계산되어 원래 개수를 복원합니다."],"answer":"완성되는 봉투는 4개이고 남은 연필은 3자루입니다. 4 * 5 + 3 = 23으로 나눈 결과를 확인할 수 있습니다."},"misconception":{"question":"//는 /의 결과에서 소수점 아래만 지우는 연산인가요?","answer":"//는 나눈 값을 음의 무한대 방향으로 내립니다. 양수에서는 소수 부분을 버린 것처럼 보이지만, 음수에서는 결과가 달라집니다. 예를 들어 -7 / 3은 약 -2.333이고 -7 // 3은 -3입니다. //가 언제나 int형을 만드는 것도 아닙니다. 정수끼리 계산하면 int 결과이고, float가 들어간 7.0 // 3 같은 계산은 2.0이라는 float 결과입니다."},"keypoints":["int는 정수, float는 실수 계산에 쓰이는 자료형입니다. /는 정수끼리 나누어도 float 결과를 만듭니다.","//는 나눈 값을 아래쪽 정수 방향으로 내리고, %는 그 몫에 맞는 나머지를 구합니다. 음수에서도 같은 규칙을 적용합니다.","괄호와 연산 우선순위가 계산 순서를 결정합니다. float는 일부 소수를 가까운 값으로 저장할 수 있습니다."],"examples":[{"question":"1000을 4로 나눈 값을 /와 //로 각각 계산하여 한 줄씩 출력하세요. 나누어떨어지는데도 두 결과의 표기가 어떻게 다른지 설명해 보세요.","skill":"나눗셈 결과의 자료형","solution":{"answer":"/의 출력은 250.0이고 //의 출력은 250입니다.","code":{"source":"print(1000 / 4)\nprint(1000 // 4)","kind":"python","output":"250.0\n250","error":null}},"explanation":"정수끼리 계산해도 /는 float 결과를 만듭니다. 이 예의 //는 정수 두 개를 사용한 내림 나눗셈이므로 int 결과를 만듭니다."},{"question":"사탕 29개를 6개씩 봉투에 담으려고 합니다. candies와 bag_size에 값을 대입하고, 완성되는 봉투 수와 남은 사탕 수를 각각 구해 출력하세요. 마지막에는 묶음과 나머지를 합쳐 29가 되는지도 출력해 확인하세요.","skill":"묶음 수와 나머지 구하기","solution":{"answer":"완성되는 봉투는 4개, 남은 사탕은 5개입니다. 4 * 6 + 5는 29입니다.","code":{"source":"candies = 29\nbag_size = 6\nfull_bags = candies // bag_size\nleftover = candies % bag_size\nprint(full_bags)\nprint(leftover)\nprint(full_bags * bag_size + leftover)","kind":"python","output":"4\n5\n29","error":null}},"explanation":"사탕 개수는 정수입니다. 완전한 묶음 수는 //로, 묶고 남은 양은 %로 구하면 나눗셈의 서로 다른 목적을 분리할 수 있습니다."},{"question":"아래 식은 2와 3을 먼저 더한 값을 제곱하려던 코드입니다. 현재 출력부터 예상하고 실행한 뒤, 괄호를 추가해 원하는 결과 25가 나오도록 고치세요. **의 의미와 괄호의 역할도 설명하세요.","skill":"거듭제곱과 괄호로 의도 표현","solution":{"answer":"원래 코드는 3 ** 2를 먼저 계산하여 11을 출력합니다. (2 + 3) ** 2로 고치면 5를 제곱한 25가 됩니다.","code":{"source":"print((2 + 3) ** 2)","kind":"python","output":"25","error":null}},"explanation":"**는 거듭제곱이고 덧셈보다 먼저 계산합니다. 원하는 밑이 두 수의 합 전체라면 그 범위를 괄호로 분명하게 표시해야 합니다.","code":"print(2 + 3 ** 2)","codeKind":"python"},{"question":"-10을 3으로 나누는 //와 %를 각각 실행해 보세요. quotient와 remainder에 결과를 대입하고 두 값을 출력한 뒤, quotient * 3 + remainder도 출력하세요. 왜 몫이 -3이 아닌지 설명하세요.","skill":"음수의 내림 나눗셈","solution":{"answer":"몫은 -4, 나머지는 2이고, -4 * 3 + 2는 원래 수 -10입니다.","code":{"source":"quotient = -10 // 3\nremainder = -10 % 3\nprint(quotient)\nprint(remainder)\nprint(quotient * 3 + remainder)","kind":"python","output":"-4\n2\n-10","error":null}},"explanation":"나눈 값 약 -3.333보다 크지 않은 가장 가까운 정수는 -4입니다. //는 0 쪽으로 소수 부분을 지우는 연산이 아니며, %의 결과는 이 몫과 함께 원래 수를 복원합니다."},{"question":"0.1 + 0.2와 0.5 + 0.25를 각각 출력하는 코드를 작성해 실행하세요. 수학에서 기대하는 값과 출력을 비교한 뒤, 첫 결과의 긴 끝자리가 왜 나타나는지 한 문장으로 적어 보세요.","skill":"실수 근사의 경계 관찰","solution":{"answer":"출력은 0.30000000000000004와 0.75입니다. float가 일부 소수를 정확히 저장하지 못하고 가까운 값으로 표현하기 때문에 작은 차이가 보일 수 있습니다.","code":{"source":"print(0.1 + 0.2)\nprint(0.5 + 0.25)","kind":"python","output":"0.30000000000000004\n0.75","error":null}},"explanation":"소수점을 썼다는 이유만으로 계산이 항상 정확하거나 항상 눈에 띄게 어긋나는 것은 아닙니다. 0.5와 0.25는 이 표현 방식으로 정확히 나타낼 수 있으므로 두 사례를 구분합니다."}]},{"id":"python-l008","order":3,"title":"문자열과 숫자 변환","subtitle":"같아 보이는 값도 맡길 일에 따라 필요한 타입이 다릅니다.","minutes":11,"goal":"문자열과 숫자의 타입을 확인하고, 계산이나 표시 목적에 맞게 변환하며 실패와 정보 손실을 설명한다.","intro":"화면에 12가 보인다고 해서 언제나 숫자 12를 가지고 있는 것은 아닙니다. 글자로 적힌 수량은 계산하기 전에 숫자로 읽어야 하고, 계산한 수량을 문장에 붙이려면 다시 글자로 나타낼 필요가 있습니다. 변환은 따옴표를 눈으로 지우는 요령이 아니라, 값에 어떤 일을 맡길지 정하는 과정입니다.","sections":[{"title":"타입은 값이 어떤 종류인지 알려 줍니다.","body":["앞에서 숫자와 문자열을 변수 이름에 연결했습니다. 이제 그 값의 종류를 타입이라고 부릅니다. 정수의 타입 이름은 int, 소수를 표현하는 부동소수점 수는 float, 문자열은 str입니다. 타입은 어떤 연산을 할 수 있고 그 연산을 어떻게 해석할지에 관계됩니다.","print만 보면 문자열 \"12\"와 정수 12가 모두 12로 보일 수 있습니다. type(...)은 전달한 값의 타입을 알려 줍니다. print(type(text))처럼 결과를 출력했을 때 <class 'str'>가 나오면 문자열이라는 뜻입니다. 여기서는 class라는 단어의 세부 의미보다 안쪽 타입 이름을 읽으면 됩니다."],"code":{"source":"text = \"12\"\nnumber = 12\nprint(text)\nprint(number)\nprint(type(text))\nprint(type(number))\nprint(type(12.0))","kind":"python","output":"12\n12\n<class 'str'>\n<class 'int'>\n<class 'float'>","error":null,"caption":"출력 모양이 같아도 type으로 확인한 값의 종류는 다를 수 있습니다."}},{"title":"계산하려면 문자열을 숫자로 읽습니다.","body":["int(\"12\")는 정수를 나타내는 문자열을 읽어 정수 12를 만듭니다. float(\"2.5\")는 소수를 나타내는 문자열을 읽어 float 값 2.5를 만듭니다. int와 float는 타입의 이름이면서, 괄호에 전달한 값을 해당 타입으로 변환할 때도 사용합니다.","변환 결과를 다른 이름에 연결하면 원래 문자열과 변환한 숫자를 각각 사용할 수 있습니다. int(text_count)를 실행했다고 text_count의 값이 저절로 바뀌지는 않습니다. 변환한 결과를 무엇에 사용할지, 어느 이름에 연결할지도 코드로 적어야 합니다.","변환 뒤에는 숫자끼리 덧셈이나 곱셈을 할 수 있습니다. 문자열이 숫자처럼 보인다는 이유만으로 Python이 계산 목적을 추측해 자동으로 변환하지는 않습니다."],"code":{"source":"text_count = \"12\"\ncount = int(text_count)\nweight = float(\"2.5\")\nprint(count + 3)\nprint(weight + 0.5)\nprint(type(text_count))","kind":"python","output":"15\n3.0\n<class 'str'>","error":null,"caption":"숫자로 변환한 값으로 계산해도 text_count는 원래 문자열을 가리킵니다."}},{"title":"문장에 붙일 때는 숫자를 문자열로 나타냅니다.","body":["문자열끼리 +를 쓰면 글자를 이어 붙입니다. 예를 들어 \"개수: \" + \"12\"는 \"개수: 12\"가 됩니다. 반면 \"개수: \" + 12처럼 문자열과 정수를 바로 연결하면 TypeError가 납니다. 문자열 연결에 맞지 않는 종류의 값이 함께 전달됐기 때문입니다.","str(12)는 숫자 12를 나타내는 문자열 \"12\"를 만듭니다. 따라서 \"개수: \" + str(count)처럼 각 부분을 문자열로 맞추어 연결할 수 있습니다. 계산할 때는 숫자, 문장을 만들 때는 문자열이라는 목적을 구분하세요. str(count) 역시 count에 연결된 원래 숫자를 바꾸지 않습니다."],"code":{"source":"count = 12\nmessage = \"개수: \" + str(count)\nprint(message)\nprint(type(count))","kind":"python","output":"개수: 12\n<class 'int'>","error":null,"caption":"표시에 쓸 문자열을 만들고도 원래 count로는 계속 숫자 계산을 할 수 있습니다."}},{"title":"변환에는 받아들일 수 있는 형태와 잃는 정보가 있습니다.","body":["int(\"3.5\")는 ValueError를 일으킵니다. int가 정수로 읽을 문자열에 소수점이 있기 때문입니다. 3.5를 그대로 사용하려는 목적이라면 float(\"3.5\")가 맞습니다. int(\"세 개\")처럼 숫자로 해석할 수 없는 글도 변환되지 않습니다. Python이 필요한 숫자만 알아서 골라내는 기능은 아닙니다.","이미 float인 수를 int에 전달하는 것은 다릅니다. int(3.9)는 3, int(-3.9)는 -3처럼 소수 부분을 없애고 0 쪽으로 정수를 만듭니다. 반올림도 아니고 음수를 더 작은 정수로 내리는 것도 아닙니다. int(float(\"3.5\"))는 실행되지만 결과가 3이므로, 소수 부분을 버려도 되는 목적일 때만 사용합니다.","형태의 정보도 달라질 수 있습니다. int(\"003\")은 3이고, 이를 str로 다시 바꿔도 원래의 003 모양이 돌아오지는 않습니다. 개수를 계산할 값인지, 앞의 0까지 보존할 번호표인지 먼저 구분해야 하는 이유입니다."],"code":{"source":"print(float(\"3.5\"))\nprint(int(3.9))\nprint(int(-3.9))\nprint(int(float(\"3.5\")))","kind":"python","output":"3.5\n3\n-3\n3","error":null,"caption":"첫 줄은 소수를 유지하고, int로 바꾼 값에서는 소수 부분이 사라집니다."}}],"worked":{"question":"가격 \"1250\"과 수량 \"3\"이 문자열로 주어졌습니다. 총액을 계산하고 총액: 3750원이라는 문장으로 보여 주려면 어떤 변환이 필요할까요?","code":{"source":"price_text = \"1250\"\nquantity_text = \"3\"\nprice = int(price_text)\nquantity = int(quantity_text)\ntotal = price * quantity\nprint(total)\nprint(\"총액: \" + str(total) + \"원\")","kind":"python","output":"3750\n총액: 3750원","error":null,"caption":"코드에 미리 적어 둔 문자열로 계산합니다. 키보드 입력을 받는 프로그램은 아닙니다."},"steps":["처음 두 값은 따옴표로 적힌 문자열입니다. 가격과 수량을 계산에 쓰려고 각각 int로 읽어 정수를 만듭니다.","두 정수를 곱한 total은 정수 3750입니다. print(total)로 계산 결과를 먼저 확인합니다.","출력 문장을 만들 때는 str(total)로 숫자를 문자열로 나타냅니다. 문장 앞뒤의 문자열과 +로 연결하여 총액: 3750원을 만듭니다."],"answer":"계산 전에 int로 숫자를 만들고, 문장과 연결할 때 str로 나타냅니다. 각 변환의 방향은 다음에 할 일에 따라 달라집니다."},"misconception":{"question":"변환이 성공하면 원래 정보도 모두 유지된 건가요?","answer":"그렇지 않습니다. int(3.9)는 오류 없이 3을 만들지만 소수 부분이 사라집니다. int(\"003\")도 3을 만들지만 앞의 0 두 개를 보존하지 않습니다. 또 변환 결과를 다른 이름에 연결했다면 원래 변수의 문자열은 그대로 남습니다. 변환 성공 여부와 필요한 정보가 유지됐는지, 어떤 이름에 결과를 연결했는지를 각각 확인해야 합니다."},"keypoints":["type으로 값의 종류를 확인합니다. 출력 모양이 같아도 문자열과 숫자는 다를 수 있습니다.","계산용 문자열은 int·float로 읽고, 숫자를 문장에 연결할 때는 str로 나타냅니다. 변환 결과를 사용해야 하며 원래 이름이 자동으로 바뀌지는 않습니다.","int(\"3.5\")는 실패하고 float(\"3.5\")는 소수를 유지합니다. int에 float를 전달하면 0 방향으로 소수 부분을 없애므로 필요한 정보의 손실도 확인합니다."],"examples":[{"question":"아래 코드를 직접 적어 실행하세요. 첫 두 출력은 같은데 뒤의 두 출력은 왜 다른지 설명하세요. 이어서 number를 8.0으로 바꾸었을 때 number의 타입이 어떻게 달라지는지도 확인하세요.","skill":"출력 모양과 타입 구분","solution":{"answer":"처음에는 8과 8이 나오고, 타입은 str과 int입니다. number를 8.0으로 바꾸면 그 값의 출력은 8.0, 타입은 float가 됩니다.","code":{"source":"text = \"8\"\nnumber = 8.0\nprint(text)\nprint(number)\nprint(type(text))\nprint(type(number))","kind":"python","output":"8\n8.0\n<class 'str'>\n<class 'float'>","error":null,"caption":"number를 8.0으로 바꾼 뒤의 코드입니다."}},"explanation":"type은 화면에 그려진 글자의 모양이 아니라 전달한 값의 종류를 확인합니다. text는 변환하거나 다시 대입하지 않았으므로 계속 문자열입니다.","code":"text = \"8\"\nnumber = 8\nprint(text)\nprint(number)\nprint(type(text))\nprint(type(number))","codeKind":"python"},{"question":"아래 코드는 문자열로 적힌 20에 숫자 5를 더하려다 멈춥니다. 오류 종류를 확인한 뒤, 숫자 덧셈 결과 25가 나오도록 고치세요. 원래 value가 여전히 문자열인지도 type으로 확인하세요.","skill":"타입에 맞는 변환으로 오류 수정","solution":{"answer":"원래 코드는 TypeError가 납니다. int(value) + 5로 계산하면 25가 나오며, value의 타입은 여전히 str입니다.","code":{"source":"value = \"20\"\nprint(int(value) + 5)\nprint(type(value))","kind":"python","output":"25\n<class 'str'>","error":null}},"explanation":"문자열과 정수를 바로 +로 더할 수 없습니다. int로 만든 정수와 5를 더하면 숫자 덧셈을 수행합니다. 원래 value에 변환 결과를 다시 대입하지 않았으므로 원래 문자열은 유지됩니다.","code":"value = \"20\"\nprint(value + 5)","codeKind":"python","codeLabel":"수정할 코드"},{"question":"아래 파일을 실행해 오류 종류를 확인하세요. 소수 3.5를 유지한 채 1을 더해 4.5를 출력하도록 변환 한 곳을 고치세요. int(float(text))로 바꾸는 것이 이번 목표에 맞지 않는 이유도 적으세요.","skill":"문자열의 형태와 변환 목적","solution":{"answer":"int(text)에서 ValueError가 납니다. float(text)로 고치면 4.5가 출력됩니다. int(float(text))는 3을 만들므로 1을 더해도 4가 되어 목표와 다릅니다.","code":{"source":"text = \"3.5\"\nvalue = float(text)\nprint(value + 1)","kind":"python","output":"4.5","error":null}},"explanation":"int는 문자열 \"3.5\"를 정수의 표기로 받아들이지 않습니다. 소수를 보존하려는 요구에는 float 변환이 맞으며, 오류만 없애고 소수 부분을 버리면 원래 요구를 만족하지 못합니다.","code":"text = \"3.5\"\nvalue = int(text)\nprint(value + 1)","codeKind":"python","codeLabel":"소수 부분을 유지하도록 고칠 코드"},{"question":"int(4.9)와 int(-4.9)를 각각 출력하는 코드를 작성하세요. 결과를 먼저 예상한 뒤 실행하고, 반올림이나 음수 쪽으로 내리는 계산과 어떻게 다른지 설명하세요.","skill":"float를 정수로 바꿀 때의 손실","solution":{"answer":"결과는 4와 -4입니다. 양수와 음수 모두 소수 부분을 없애며 0 쪽의 정수가 됩니다.","code":{"source":"print(int(4.9))\nprint(int(-4.9))","kind":"python","output":"4\n-4","error":null}},"explanation":"4.9를 반올림하면 5이지만 int(4.9)는 4입니다. -4.9보다 작은 정수로 내리면 -5이지만 int(-4.9)는 -4입니다. 변환의 규칙을 계산 목적과 구분해야 합니다."},{"question":"아래 두 문자열은 끝낸 레슨 수와 남은 레슨 수입니다. 두 수를 더해 전체 6개라는 한 줄을 출력하세요. 숫자 계산과 문자열 연결에 각각 어떤 변환을 사용했는지 적으세요.","skill":"계산과 표시를 위한 변환 조합","solution":{"answer":"두 문자열을 정수로 바꾸어 더한 뒤, 합을 str로 나타내어 문장에 연결합니다. 아래는 가능한 풀이의 한 가지입니다.","code":{"source":"completed_text = \"4\"\nremaining_text = \"2\"\ncompleted = int(completed_text)\nremaining = int(remaining_text)\ntotal = completed + remaining\nprint(\"전체 \" + str(total) + \"개\")","kind":"python","output":"전체 6개","error":null}},"explanation":"문자열 \"4\"와 \"2\"를 그대로 +로 연결하면 \"42\"가 됩니다. 합계가 필요하므로 먼저 숫자로 읽고, 마지막에 출력할 문장을 만들 때 다시 문자열로 나타냅니다.","code":"completed_text = \"4\"\nremaining_text = \"2\"","codeKind":"python"}]},{"id":"python-l009","order":4,"title":"비교·불리언·논리 연산","subtitle":"값을 비교해 얻은 참과 거짓으로 여러 조건을 정확히 표현합니다.","minutes":11,"goal":"비교 결과를 불리언 값으로 다루고 and·or·not과 괄호로 요구에 맞는 조건을 표현한다.","intro":"점수가 기준에 도달했는지, 두 가지 준비가 모두 끝났는지처럼 계산 결과에 질문을 던질 때가 있습니다. 이런 질문의 답도 프로그램이 다룰 수 있는 값입니다. 이번 레슨에서는 참과 거짓을 만들고 결합하는 데 집중합니다. 그 결과에 따라 실행할 일을 나누는 조건문은 뒤에서 배우며, 지금은 print로 판단 결과를 확인합니다.","sections":[{"title":"비교의 답도 하나의 값입니다.","body":["두 값을 비교한 결과는 참을 나타내는 True 또는 거짓을 나타내는 False입니다. 이 두 값의 타입을 bool, 불리언이라고 부릅니다. 첫 글자를 대문자로 쓰고 따옴표로 감싸지 않습니다. \"False\"는 글자가 들어 있는 문자열이므로 불리언 False와 구분합니다.","==는 같은지, !=는 다른지 확인합니다. >와 <는 큰지와 작은지, >=와 <=는 크거나 같은지와 작거나 같은지 확인합니다. 특히 >=와 <=는 두 값이 같을 때도 True입니다. 같은 값일 때의 결과가 경계를 포함하는지 결정합니다.","한 개의 =는 오른쪽 값을 이름에 연결하는 대입입니다. 두 개인 ==는 값을 비교하는 연산입니다. score = 80으로 값을 연결한 뒤 score == 80을 확인해도 score에 연결된 값 자체를 바꾸지는 않습니다."],"code":{"source":"score = 80\nprint(score == 80)\nprint(score != 80)\nprint(score > 80)\nprint(score >= 80)\nprint(score < 90)\nprint(score <= 80)\nprint(type(score == 80))","kind":"python","output":"True\nFalse\nFalse\nTrue\nTrue\nTrue\n<class 'bool'>","error":null,"caption":"각 비교의 결과가 불리언 값이며, 그 값을 출력해 확인할 수 있습니다."}},{"title":"and와 or는 서로 다른 요구를 표현합니다.","body":["불리언 값 둘을 and로 연결하면 두 값이 모두 True일 때만 True입니다. 준비 두 가지가 모두 끝나야 하는 상황에 어울립니다. or로 연결하면 하나라도 True일 때 True이며, 둘 다 True인 경우도 포함합니다. 둘 다 False일 때만 False입니다.","아래에서는 표가 있다는 값은 True이고 초대장이 있다는 값은 False입니다. 둘을 모두 가지고 있다는 판단과 하나 이상 가지고 있다는 판단은 서로 다른 결과를 만듭니다. 단어를 외우기보다 질문이 ‘모두’인지 ‘하나 이상’인지 먼저 읽어 보세요.","이 레슨에서는 and와 or 양쪽에 불리언 값이나 비교 결과만 놓습니다. 이 범위에서는 결과도 불리언입니다. 일반 숫자나 문자열에 적용한 and와 or가 언제나 True 또는 False를 돌려주는 것으로 확대해서 생각하지는 않습니다."],"code":{"source":"has_ticket = True\nhas_invitation = False\nprint(has_ticket and has_invitation)\nprint(has_ticket or has_invitation)\nprint(False or False)","kind":"python","output":"False\nTrue\nFalse","error":null,"caption":"둘 모두 필요한 경우와 하나 이상이면 되는 경우를 같은 값으로 비교합니다."}},{"title":"not은 참과 거짓을 뒤집습니다.","body":["불리언 값 앞의 not은 True를 False로, False를 True로 바꿉니다. 예를 들어 is_closed가 휴장 여부라면 not is_closed는 휴장이 아니라는 판단입니다. 질문을 반대로 읽어야 할 때 사용합니다.","비교 전체의 결과를 뒤집고 싶다면 not (age >= 18)처럼 괄호로 묶어 읽을 수 있습니다. age가 15일 때 age >= 18은 False이고, 그 결과를 not으로 뒤집으면 True입니다. 먼저 비교가 답하는 질문과 그 반대 질문을 각각 말로 풀어 보세요."],"code":{"source":"is_closed = False\nprint(not is_closed)\nage = 15\nprint(not (age >= 18))","kind":"python","output":"True\nTrue","error":null,"caption":"첫 줄의 판단은 휴장이 아니라는 뜻, 두 번째 판단은 18 이상이 아니라는 뜻입니다."}},{"title":"괄호로 어떤 조건들을 먼저 묶는지 드러냅니다.","body":["배운 연산을 함께 쓰면 산술 연산과 비교를 먼저 묶고, 논리 연산은 not, and, or 순으로 묶습니다. 우선순위는 식의 묶음을 정하는 규칙입니다. 예를 들어 True or False and False는 True or (False and False)로 읽습니다. 왼쪽 True만으로도 하나 이상이 참이라는 요구를 만족하므로 전체 결과는 True입니다.","반면 (True or False) and False는 괄호로 묶은 결과 True와 마지막 False를 and로 연결하므로 False입니다. 기호가 같아도 묶음이 다르면 질문이 달라질 수 있습니다. 여러 조건을 적을 때는 읽는 사람이 의도를 바로 알 수 있도록 필요한 묶음을 괄호로 표시하세요.","비교 두 개를 연결할 때도 (age >= 7) and (age <= 12)처럼 각 비교를 분명히 적을 수 있습니다. 이렇게 쓰면 7 이상이면서 12 이하라는 범위를 읽기 쉽습니다. 비교식 안의 =와 논리 연결에 필요한 단어를 빠뜨리지 않았는지 확인하세요."],"code":{"source":"print(True or False and False)\nprint((True or False) and False)\nprint(not (3 < 5))","kind":"python","output":"True\nFalse\nFalse","error":null,"caption":"첫 두 줄은 묶음의 차이, 마지막 줄은 비교 결과를 뒤집는 동작을 확인합니다."}}],"worked":{"question":"체험에 참여하려면 나이가 7세 이상 12세 이하이고, 표가 있으며, 휴장이 아니어야 합니다. 12세이고 표가 있으며 휴장이 아니라면 참여 조건을 만족할까요?","code":{"source":"age = 12\nhas_ticket = True\nis_closed = False\nin_range = (age >= 7) and (age <= 12)\ncan_enter = in_range and has_ticket and (not is_closed)\nprint(in_range)\nprint(can_enter)","kind":"python","output":"True\nTrue","error":null,"caption":"실행을 나누는 조건문 없이, 조건이 맞는지를 불리언 값으로 계산합니다."},"steps":["age >= 7과 age <= 12가 모두 True입니다. 같은 값도 허용하는 <=를 사용하므로 12세는 범위에 들어갑니다. 두 비교를 and로 연결한 in_range는 True입니다.","has_ticket은 True이고 is_closed는 False입니다. not is_closed는 휴장이 아니라는 뜻의 True가 됩니다.","세 조건을 and로 연결하면 모두 True일 때 참여 조건이 만족됩니다. can_enter는 True이며, print로 그 판단을 확인합니다."],"answer":"나이 범위, 표 보유, 휴장이 아님이라는 세 조건이 모두 맞으므로 can_enter는 True입니다."},"misconception":{"question":"조건들을 or로 연결하면 둘 중 정확히 하나만 참이어야 하나요?","answer":"아닙니다. 불리언 값끼리의 or는 하나 이상이 True이면 True입니다. True or True도 True입니다. 둘 다 필요한 요구는 and로, 하나 이상이면 되는 요구는 or로 표현합니다. 일상에서 쓰는 ‘또는’이라는 말만 보고 고르지 말고 두 조건이 모두 참인 경우도 허용하는지 확인하세요."},"keypoints":["비교는 True 또는 False를 만듭니다. =는 대입, ==는 같은지 비교이며 >=와 <=는 경계의 같은 값도 포함합니다.","불리언끼리 and는 모두 참, or는 하나 이상 참을 확인합니다. not은 참과 거짓을 뒤집습니다.","논리 연산의 우선순위는 not, and, or이며, 괄호로 묶음을 바꾸면 의미도 달라질 수 있습니다. 요구하는 조건을 먼저 말로 풀어 봅니다."],"examples":[{"question":"아래 여섯 비교의 출력을 먼저 예상하고 직접 실행하세요. >와 >=가 서로 다른 결과를 내는 이유를 설명하세요. 마지막에 출력한 score가 비교 때문에 바뀌었는지도 확인하세요.","skill":"비교 기호와 경계 읽기","solution":{"answer":"비교 결과는 True, False, False, True, True, True 순서이고, 마지막 score는 70입니다. >는 같을 때 False지만 >=는 같을 때도 True입니다.","code":{"source":"score = 70\nprint(score == 70)\nprint(score != 70)\nprint(score > 70)\nprint(score >= 70)\nprint(score < 80)\nprint(score <= 70)\nprint(score)","kind":"python","output":"True\nFalse\nFalse\nTrue\nTrue\nTrue\n70","error":null}},"explanation":"각 비교는 불리언 값을 계산할 뿐 score를 다시 대입하지 않습니다. 기호에 =가 붙은 >=와 <=는 경계값도 포함합니다.","code":"score = 70\nprint(score == 70)\nprint(score != 70)\nprint(score > 70)\nprint(score >= 70)\nprint(score < 80)\nprint(score <= 70)\nprint(score)","codeKind":"python"},{"question":"count에 정수 3을 대입한 뒤, count가 3과 같은지 비교한 결과를 same이라는 이름에 연결하세요. same, same의 타입, count를 각각 출력하세요. 값을 연결할 때와 비교할 때 어떤 기호를 썼는지 설명하세요.","skill":"대입과 비교·불리언 구분","solution":{"answer":"same은 True, 타입은 bool, count는 3입니다. 대입에는 =, 같은지 비교하는 식에는 ==를 사용합니다.","code":{"source":"count = 3\nsame = count == 3\nprint(same)\nprint(type(same))\nprint(count)","kind":"python","output":"True\n<class 'bool'>\n3","error":null}},"explanation":"same = count == 3은 오른쪽의 비교 결과를 계산한 뒤 그 불리언 값을 same에 연결합니다. count에 연결된 숫자 3은 그대로 유지됩니다."},{"question":"아래 값으로 표와 초대장을 모두 가지고 있는지, 하나 이상 가지고 있는지를 각각 출력하세요. 이어서 두 값을 모두 False로 바꾸어 같은 두 판단을 다시 출력하세요.","skill":"and와 or의 요구 차이","solution":{"answer":"처음 두 판단은 False, True입니다. 두 값이 모두 False이면 두 판단 모두 False가 됩니다. 아래는 두 경우를 이어서 확인하는 예시입니다.","code":{"source":"has_ticket = True\nhas_invitation = False\nprint(has_ticket and has_invitation)\nprint(has_ticket or has_invitation)\nhas_ticket = False\nhas_invitation = False\nprint(has_ticket and has_invitation)\nprint(has_ticket or has_invitation)","kind":"python","output":"False\nTrue\nFalse\nFalse","error":null}},"explanation":"모두 필요하다는 요구는 and, 하나 이상이면 된다는 요구는 or로 표현합니다. 두 값이 모두 False이면 어느 요구도 만족하지 못합니다.","code":"has_ticket = True\nhas_invitation = False","codeKind":"python"},{"question":"age가 17일 때 18 이상이 아니라는 판단을 not과 >=를 사용해 출력하세요. 이어서 age를 18로 바꾸어 같은 판단을 다시 출력하세요. 두 결과가 다른 이유를 경계값과 연결해 설명하세요.","skill":"not과 경계값 확인","solution":{"answer":"17일 때는 True, 18일 때는 False입니다. 18은 18 이상에 포함되므로 그 결과를 뒤집으면 False가 됩니다.","code":{"source":"age = 17\nprint(not (age >= 18))\nage = 18\nprint(not (age >= 18))","kind":"python","output":"True\nFalse","error":null}},"explanation":"not (age >= 18)은 먼저 18 이상인지 비교하고 그 결과를 뒤집습니다. not이 있다고 해서 >=가 경계값을 포함하는 규칙이 사라지는 것은 아닙니다."},{"question":"회원이거나 쿠폰이 있고, 동시에 영업 중이어야 이용 가능하다고 정했습니다. 아래 코드는 영업 중이 아닌데도 True를 출력합니다. 회원 여부와 쿠폰 여부를 먼저 묶도록 괄호를 넣어 고치고, 원래 결과와 비교하세요.","skill":"조건 묶음과 우선순위 수정","solution":{"answer":"원래 코드는 True이지만, (is_member or has_coupon) and is_open으로 묶으면 False입니다. 영업 중이어야 한다는 조건이 전체에 적용됩니다.","code":{"source":"is_member = True\nhas_coupon = False\nis_open = False\nprint((is_member or has_coupon) and is_open)","kind":"python","output":"False","error":null}},"explanation":"원래 식은 is_member or (has_coupon and is_open)으로 묶입니다. is_member가 True이므로 전체 결과가 True가 됩니다. 괄호로 회원 또는 쿠폰이라는 판단을 먼저 묶어야 영업 여부까지 함께 요구할 수 있습니다.","code":"is_member = True\nhas_coupon = False\nis_open = False\nprint(is_member or has_coupon and is_open)","codeKind":"python","codeLabel":"괄호를 추가할 코드"}]},{"id":"python-l010","order":5,"title":"입력받아 계산하고 출력하기","subtitle":"읽은 문자열을 목적에 맞는 숫자로 바꾸어 계산 결과까지 연결합니다.","minutes":12,"goal":"입력받기, 숫자로 변환하기, 계산하기, 출력하기를 연결한 작은 프로그램을 작성한다.","intro":"지금까지는 코드에 적힌 값을 바꾸어 계산했습니다. 프로그램을 실행할 때마다 사용자가 다른 값을 넣을 수 있다면 코드를 고치지 않고도 여러 계산을 할 수 있습니다. 앞에서 배운 변수와 숫자 변환을 input에 연결해, 입력한 값이 결과로 바뀌는 과정을 따라가 봅시다.","sections":[{"title":"input은 한 줄을 읽어 문자열로 돌려줍니다.","body":["input()은 실행 중에 입력 한 줄을 읽는 기능입니다. PC에서 아래 파일을 실행한 뒤 입력을 기다리는 창에 수학이라고 타이핑하고 Enter를 누르세요. 이 예시에서는 안내 문장을 출력하지 않으므로 입력 전에는 아무것도 보이지 않을 수 있습니다. Enter를 누르면 그 한 줄을 읽고 다음 명령으로 넘어갑니다.","읽은 결과는 문자열입니다. text = input()은 그 문자열에 text라는 이름을 연결합니다. input은 줄 끝의 줄바꿈을 제외한 내용을 돌려주므로, 그다음 print(text)가 읽은 글자를 한 줄로 출력합니다. 숫자처럼 보이는 25를 입력해도 이 단계에서는 문자열 \"25\"입니다.","이 페이지의 입력 예시는 코드를 적는 자리가 아니라 실행 중에 넣을 값을 보여 줍니다. 따옴표를 덧붙이지 않고 각 줄을 입력한 뒤 Enter를 누릅니다. 터미널이나 IDLE 창에는 타이핑한 글자도 보일 수 있지만, 여기의 예상 출력에는 프로그램이 print로 내보낸 내용만 적습니다."],"code":{"source":"text = input()\nprint(text)","kind":"python","output":"수학","error":null,"input":"수학\n","caption":"PC에서 파일을 실행하고 수학을 입력한 뒤 Enter를 누르세요. 입력 예시와 예상 출력은 역할이 다릅니다."}},{"title":"계산하기 전에 숫자라는 뜻을 정합니다.","body":["수량을 입력받아 10을 더하려면, 읽은 문자열을 먼저 정수로 바꿔야 합니다. input이 숫자 모양을 보고 자동으로 int를 선택하지는 않습니다. 사용자가 입력한 내용이 글자인지 정수인지 실수인지는 프로그램을 만드는 사람이 목적에 맞게 정합니다.","아래에서는 number_text로 문자열을 받고 int(number_text)로 정수를 만듭니다. 그 결과에 number라는 이름을 붙인 뒤 덧셈을 합니다. 이름을 나누면 읽은 원본과 계산할 값을 구별하기 쉽습니다. 익숙해지면 number = int(input())처럼 한 줄로 쓸 수도 있으며, 이때도 먼저 input()이 끝난 뒤 int가 그 결과를 변환합니다."],"code":{"source":"number_text = input()\nnumber = int(number_text)\nresult = number + 10\nprint(result)","kind":"python","output":"17","error":null,"input":"7\n","caption":"7을 입력하면 문자열 \"7\"을 정수 7로 바꾸고 10을 더합니다."}},{"title":"여러 입력은 적힌 순서대로 한 줄씩 받습니다.","body":["두 값을 읽으려면 input을 두 번 사용합니다. 아래 코드는 첫 번째 줄을 읽어 first_text에 연결한 다음 두 번째 줄을 기다립니다. 8을 입력하고 Enter를 누른 뒤, 5를 입력하고 다시 Enter를 누르세요. 두 번째 입력까지 받으면 두 값을 변환하고 계산합니다.","한 번의 input은 한 줄 전체를 문자열 하나로 읽습니다. 따라서 이 예시에 8 5를 한 줄로 넣으면 두 값으로 자동 분리되지 않습니다. 지금은 값 하나마다 한 줄을 입력하는 약속으로 연습합니다. 어떤 순서로 무엇을 넣을지도 프로그램의 사용 방법에 포함됩니다."],"code":{"source":"first_text = input()\nsecond_text = input()\nfirst = int(first_text)\nsecond = int(second_text)\ntotal = first + second\nprint(total)","kind":"python","output":"13","error":null,"input":"8\n5\n","caption":"첫 줄에는 8, 둘째 줄에는 5를 입력합니다. 각각의 input이 한 줄씩 읽습니다."}},{"title":"입력의 의미에 맞는 변환을 선택합니다.","body":["개수처럼 정수로 다룰 값에는 int를 쓰고, 1.5처럼 소수 부분이 필요한 길이에는 float를 쓸 수 있습니다. 아래 코드는 입력한 길이의 두 배를 계산하므로 float로 변환합니다. 변환을 생략하거나 소수 부분을 버리면 의도한 계산과 달라질 수 있습니다.","이 레슨의 입력은 문제에서 정한 숫자 형식에 맞는다고 가정합니다. 예를 들어 float로 바꿀 입력은 1.5처럼 적고, 1.5m처럼 단위 글자를 함께 넣지 않습니다. 숫자로 읽을 수 없는 글자나 빈 줄은 변환할 때 ValueError를 낼 수 있습니다. 입력을 다시 요청하거나 오류를 처리하는 방법은 뒤 챕터에서 배우고, 지금은 어떤 값과 형식을 기대하는지 먼저 확인합니다."],"code":{"source":"length_text = input()\nlength = float(length_text)\ndoubled = length * 2\nprint(doubled)","kind":"python","output":"3.0","error":null,"input":"1.5\n","caption":"1.5를 입력합니다. float로 계산한 결과 3.0은 수로는 3과 같지만 실수 값의 출력입니다."}}],"worked":{"question":"공책 한 권의 가격과 권수를 두 줄로 입력받아 총금액을 출력해 봅시다. 첫 줄은 가격 1200, 둘째 줄은 권수 3입니다. 두 값은 단위 글자나 쉼표 없는 정수로 입력합니다.","code":{"source":"price_text = input()\ncount_text = input()\nprice = int(price_text)\ncount = int(count_text)\ntotal = price * count\nprint(total)","kind":"python","output":"3600","error":null,"input":"1200\n3\n","caption":"1200을 입력하고 Enter, 이어서 3을 입력하고 Enter를 누릅니다. 결과로 3600이 출력됩니다."},"steps":["첫 번째 input은 문자열 \"1200\"을, 두 번째 input은 문자열 \"3\"을 읽습니다. 아직 두 값 모두 문자열입니다.","int로 각각 변환하여 price는 정수 1200, count는 정수 3에 연결합니다. 계산에 쓰기 전에 필요한 종류의 값으로 바꾼 것입니다.","price * count로 3600을 계산하고 그 값에 total이라는 이름을 연결합니다. print(total)이 화면에 총금액을 보여 줍니다.","같은 파일을 다시 실행하여 가격과 권수를 새로 입력하면 그 입력으로 다시 계산합니다. 코드를 고치지 않아도 입력이 달라지면 결과가 달라질 수 있습니다."],"answer":"입력은 1200과 3 두 줄이고, 프로그램의 출력은 3600 한 줄입니다. 읽기 → 변환 → 계산 → 출력의 각 단계가 서로 다른 역할을 합니다."},"misconception":{"question":"입력할 때 따옴표 없이 25를 적었으니 input도 숫자 25를 돌려주나요?","answer":"아닙니다. 코드에 적은 숫자 리터럴과 실행 중 입력한 글자는 읽는 방식이 다릅니다. input()은 25라는 글자를 문자열 \"25\"로 돌려줍니다. 정수 덧셈을 하려면 int로 변환해야 합니다. print로 보이는 모양이 같아도 문자열과 숫자는 서로 다른 값의 종류입니다."},"keypoints":["input()은 실행 중 한 줄을 읽어, 줄 끝의 줄바꿈을 뺀 문자열을 돌려줍니다.","계산할 입력은 목적에 맞게 int 또는 float로 변환한 다음 사용합니다.","입력 순서와 형식을 정하고, 읽기 → 변환 → 계산 → 출력 순서로 결과를 확인합니다."],"examples":[{"question":"아래 파일을 실행하고 25를 입력한 뒤 Enter를 누르세요. 먼저 출력 두 줄을 예상하고, text의 값 종류와 마지막 줄이 덧셈 결과가 아닌 이유를 설명해 보세요.","code":"text = input()\nprint(type(text))\nprint(text + \"0\")","codeKind":"python","codeLabel":"입력값의 종류를 확인할 코드","skill":"입력 문자열의 의미","solution":{"answer":"예시 답: 첫 줄에는 <class 'str'>, 둘째 줄에는 250이 출력됩니다. text는 문자열 \"25\"이고 \"0\"도 문자열이므로 두 글자 묶음을 이어 붙입니다.","code":{"source":"text = input()\nprint(type(text))\nprint(text + \"0\")","kind":"python","output":"<class 'str'>\n250","error":null,"input":"25\n","caption":"type으로 값 종류를 확인하면 출력 모양만 보고 숫자로 오해하는 일을 줄일 수 있습니다."}},"explanation":"input은 숫자 모양의 입력도 문자열로 읽습니다. 문자열끼리의 +는 글자를 이어 붙이므로 정수 25에 0을 더한 것과 다릅니다."},{"question":"하루 공부 시간(분)과 공부할 일수를 각각 정수로 입력받아 총 공부 시간을 분 단위로 출력하는 프로그램을 작성하세요. 첫 줄에는 20, 둘째 줄에는 3을 입력해 결과를 확인하세요.","skill":"두 정수 입력의 계산","solution":{"answer":"예시 답: 두 입력을 int로 바꾸고 곱하면 60이 출력됩니다. 변수 이름이나 변환을 나누어 쓰는 방식은 달라도 됩니다.","code":{"source":"minutes_per_day = int(input())\ndays = int(input())\ntotal_minutes = minutes_per_day * days\nprint(total_minutes)","kind":"python","output":"60","error":null,"input":"20\n3\n","caption":"20과 3을 서로 다른 줄로 입력하는 한 가지 풀이입니다."}},"explanation":"input을 두 번 호출하므로 두 줄이 필요합니다. 먼저 각 문자열을 정수로 바꾸면 *가 공부 시간과 일수를 수로 곱하는 계산이 됩니다."},{"question":"아래 코드는 입력한 개수에 1을 더하려 하지만 4를 입력하면 TypeError가 납니다. 입력을 정수로 바꾸도록 수정한 뒤, 4를 넣었을 때 5가 출력되는지 확인하세요.","code":"count = input()\nnext_count = count + 1\nprint(next_count)","codeKind":"python","codeLabel":"숫자 변환이 빠진 코드","skill":"입력 변환 누락 수정","solution":{"answer":"예시 답: 첫 줄을 count = int(input())으로 바꿀 수 있습니다. 그러면 정수 4에 정수 1을 더해 5를 출력합니다.","code":{"source":"count = int(input())\nnext_count = count + 1\nprint(next_count)","kind":"python","output":"5","error":null,"input":"4\n","caption":"입력 후 계산 전에 정수로 변환한 수정 예시입니다."}},"explanation":"원래 코드의 count는 문자열이어서 정수 1과 바로 더할 수 없습니다. 1을 문자열 \"1\"로 바꾸면 41이 되므로, 개수를 하나 늘리려는 목표에는 입력값을 숫자로 바꾸는 편이 맞습니다."},{"question":"리본의 길이를 미터 단위로 입력받아 절반 길이를 출력하는 프로그램을 작성하세요. 소수 부분을 유지해야 하며, 실행할 때 단위 글자 없이 3.5를 입력하세요.","skill":"소수 입력에 맞는 변환","solution":{"answer":"예시 답: 입력을 float로 바꾸고 2로 나누면 1.75가 출력됩니다.","code":{"source":"length = float(input())\nhalf = length / 2\nprint(half)","kind":"python","output":"1.75","error":null,"input":"3.5\n","caption":"3.5미터의 절반을 계산하는 예시이며 입력에는 숫자만 적습니다."}},"explanation":"문자열 \"3.5\"는 소수 형태이므로 float로 읽어 소수 부분을 유지합니다. int(\"3.5\")는 소수 문자열을 정수로 바로 바꾸지 못해 ValueError가 납니다."},{"question":"남은 좌석 수를 정수로 입력받고, 4명이 모두 앉을 수 있는지를 True 또는 False로 출력하는 프로그램을 작성하세요. 한 번은 4, 다시 실행해서는 3을 입력하고 결과를 비교하세요.","skill":"입력값과 비교 결과 연결","solution":{"answer":"예시 답: 좌석 수가 4 이상인지 비교하여 출력합니다. 4를 입력하면 True, 파일을 다시 실행해 3을 입력하면 False가 나옵니다.","code":{"source":"seats = int(input())\nenough = seats >= 4\nprint(enough)","kind":"python","output":"True","error":null,"input":"4\n","caption":"좌석 수 4로 실행한 예시입니다. 3으로 확인할 때는 파일을 새로 실행합니다."}},"explanation":"입력을 정수로 바꾸면 좌석 수를 숫자로 비교할 수 있습니다. >=는 같은 값도 포함하므로 딱 4석일 때도 True입니다. 조건문 없이 비교 결과인 불리언 자체를 print로 보여 줄 수 있습니다."}]}],"review":[{"question":"아래 코드의 마지막 두 줄이 출력할 값을 순서대로 적은 뒤 실행하세요. original을 다시 대입한 것이 saved에도 영향을 주는지, 두 이름이 가리키는 값으로 설명해 보세요.","code":"original = 8\nsaved = original\noriginal = 11\nprint(original)\nprint(saved)","codeKind":"python","skill":"값과 이름 · 재대입 뒤의 값","solution":{"answer":"예시 답: 11 다음 줄에 8이 출력됩니다. saved는 대입 당시의 값 8에 연결되었고, original만 나중에 11로 바뀝니다.","code":{"source":"original = 8\nsaved = original\noriginal = 11\nprint(original)\nprint(saved)","kind":"python","output":"11\n8","error":null}},"explanation":"saved = original은 두 이름을 영구히 묶는 규칙이 아닙니다. 그 줄을 실행할 때 original이 가리키던 값을 saved에도 연결합니다. 이후 original의 재대입은 saved의 연결을 바꾸지 않습니다.","related":["python-l006"]},{"question":"공책 한 권의 가격이 900일 때 아래 코드를 읽고 total과 count의 최종 값을 예상하세요. 실행 후, count를 3으로 바꿨는데 total이 자동으로 2700이 되지 않는 이유를 적어 보세요.","code":"unit_price = 900\ncount = 2\ntotal = unit_price * count\ncount = 3\nprint(total)\nprint(count)","codeKind":"python","skill":"값과 이름 · 계산한 값의 연결","solution":{"answer":"예시 답: total은 1800, count는 3입니다. total에 연결된 것은 당시 계산한 값 1800이므로, count를 바꾼 것만으로 다시 계산되지는 않습니다.","code":{"source":"unit_price = 900\ncount = 2\ntotal = unit_price * count\ncount = 3\nprint(total)\nprint(count)","kind":"python","output":"1800\n3","error":null}},"explanation":"대입은 오른쪽 식을 그 순간의 값으로 계산한 뒤 결과를 이름에 연결합니다. 나중에 count가 달라졌다면 total = unit_price * count를 다시 실행해야 새 개수로 계산한 값이 연결됩니다.","related":["python-l006","python-l007"]},{"question":"아래 코드는 score를 7에서 10으로 바꾸려는 의도입니다. 실제 출력을 먼저 예상하고, 잘못 쓴 한 줄을 고쳐 10이 출력되게 하세요. =와 ==의 역할 차이도 설명해 보세요.","code":"score = 7\nscore == 10\nprint(score)","codeKind":"python","codeLabel":"대입과 비교를 확인할 코드","skill":"값과 이름 · 대입과 비교 구분","solution":{"answer":"예시 답: 원래 코드는 7을 출력합니다. 두 번째 줄을 score = 10으로 바꾸면 score가 10에 연결되어 10을 출력합니다.","code":{"source":"score = 7\nscore = 10\nprint(score)","kind":"python","output":"10","error":null,"caption":"값을 바꾸려는 의도에 맞게 대입으로 수정한 예시입니다."}},"explanation":"==는 양쪽 값이 같은지 비교할 뿐 왼쪽 이름의 값을 바꾸지 않습니다. 원래 두 번째 줄의 비교 결과는 False이지만 저장하거나 print하지 않았으므로 파일 실행 화면에는 나타나지 않습니다.","related":["python-l006","python-l009"]},{"question":"아래 두 출력값을 먼저 계산하고 실행해 확인하세요. 가격 3인 물건과 가격 5인 물건을 한 개씩 묶어 같은 묶음 4개를 산다면, 어느 식이 총금액을 나타내는지 이유를 적으세요.","code":"print(3 + 5 * 4)\nprint((3 + 5) * 4)","codeKind":"python","skill":"연산 예측 · 괄호와 계산 순서","solution":{"answer":"예시 답: 첫 줄은 23, 둘째 줄은 32입니다. 묶음 하나의 가격 3 + 5를 먼저 계산해야 하므로 둘째 식이 요구한 총금액입니다.","code":{"source":"print(3 + 5 * 4)\nprint((3 + 5) * 4)","kind":"python","output":"23\n32","error":null}},"explanation":"괄호가 없으면 곱셈 5 * 4가 덧셈보다 먼저 계산됩니다. (3 + 5)는 한 묶음의 가격을 먼저 구하라는 뜻을 코드에 분명히 나타냅니다.","related":["python-l007"]},{"question":"공 27개를 상자당 6개씩 담습니다. 아래 세 출력값을 예상하고, 그중 가득 채울 수 있는 상자 수와 남는 공 수를 나타내는 값이 무엇인지 설명하세요. 코드를 실행해 확인해 보세요.","code":"balls = 27\ncapacity = 6\nprint(balls / capacity)\nprint(balls // capacity)\nprint(balls % capacity)","codeKind":"python","skill":"연산 예측 · 나눗셈과 몫과 나머지","solution":{"answer":"예시 답: 차례로 4.5, 4, 3이 출력됩니다. 가득 채운 상자는 4개이고 남는 공은 3개입니다.","code":{"source":"balls = 27\ncapacity = 6\nprint(balls / capacity)\nprint(balls // capacity)\nprint(balls % capacity)","kind":"python","output":"4.5\n4\n3","error":null}},"explanation":"/는 이 나눗셈의 실수 결과를 구합니다. 양의 정수인 이 사례에서 //는 가득 묶을 수 있는 개수를, %는 묶은 뒤 남는 개수를 나타냅니다. 27 = 6 * 4 + 3으로도 확인할 수 있습니다.","related":["python-l006","python-l007"]},{"question":"야외 학습은 기온이 18 이상 26 이하이고 비가 오지 않을 때 가능하다고 정했습니다. 아래 두 줄의 출력을 예상한 뒤 실행하세요. 첫 번째 식에서 기온 26이 범위에 포함되는 이유도 설명하세요.","code":"temperature = 26\nraining = False\nprint(temperature >= 18 and temperature <= 26 and not raining)\nprint(temperature == 25 or raining)","codeKind":"python","skill":"연산 예측 · 비교와 불리언 연결","solution":{"answer":"예시 답: 첫 줄은 True, 둘째 줄은 False입니다. 26은 18 이상이면서 26 이하이고, raining이 False이므로 not raining은 True입니다.","code":{"source":"temperature = 26\nraining = False\nprint(temperature >= 18 and temperature <= 26 and not raining)\nprint(temperature == 25 or raining)","kind":"python","output":"True\nFalse","error":null}},"explanation":">=와 <=는 경계값이 같은 경우도 포함합니다. 첫 줄의 and로 묶인 불리언 세 값은 모두 True입니다. 둘째 줄은 26 == 25와 raining이 모두 False라서 or의 결과도 False입니다.","related":["python-l009"]},{"question":"아래 코드는 문자열로 적힌 컵 개수 \"8\"에 2개를 더하려 합니다. 실행했을 때의 오류 종류를 확인하고, 숫자 덧셈 결과 10이 나오도록 고치세요. 글자 82가 나오게 바꾸는 것은 목표가 아닙니다.","code":"cups = \"8\"\nprint(cups + 2)","codeKind":"python","codeLabel":"값의 종류가 맞지 않는 코드","skill":"변환 오류 · 문자열과 숫자의 덧셈","solution":{"answer":"예시 답: 원본은 TypeError가 납니다. cups를 int로 바꾸어 정수끼리 더하면 10이 출력됩니다.","code":{"source":"cups = \"8\"\nprint(int(cups) + 2)","kind":"python","output":"10","error":null,"caption":"컵 개수를 정수로 바꾼 뒤 계산하는 수정 예시입니다."}},"explanation":"문자열과 정수는 +로 바로 더할 수 없습니다. int(\"8\")은 정수 8을 만들고, 그때부터 + 2가 숫자 덧셈이 됩니다. 변환은 어떤 의미의 계산을 원하는지에 맞게 선택합니다.","related":["python-l007","python-l008"]},{"question":"높이 2.5를 두 배로 계산하려는 아래 코드에서 오류가 나는 줄과 오류 종류를 확인하세요. 소수 부분을 유지하면서 5.0을 출력하도록 변환을 고쳐 보세요.","code":"height_text = \"2.5\"\nheight = int(height_text)\nprint(height * 2)","codeKind":"python","codeLabel":"소수 문자열의 변환을 고칠 코드","skill":"변환 오류 · 정수와 실수 변환 선택","solution":{"answer":"예시 답: 두 번째 줄의 int(height_text)에서 ValueError가 납니다. float(height_text)로 바꾸면 2.5의 소수 부분을 유지하여 5.0을 출력합니다.","code":{"source":"height_text = \"2.5\"\nheight = float(height_text)\nprint(height * 2)","kind":"python","output":"5.0","error":null,"caption":"소수 형태의 문자열을 float로 변환한 수정 예시입니다."}},"explanation":"int는 \"2.5\"처럼 소수점이 있는 문자열을 정수 형식으로 바로 읽지 못합니다. 먼저 float로 바꾼 뒤 다시 int를 적용하면 소수 부분을 버리므로, 이 문제에서는 float 값을 그대로 계산에 씁니다.","related":["python-l007","python-l008"]},{"question":"낸 돈, 물건 한 개의 가격, 살 개수를 이 순서로 세 줄 입력받아 거스름돈을 출력하는 프로그램을 작성하세요. 모두 정수이며 낸 돈은 총금액 이상입니다. 10000, 1200, 3을 따옴표나 쉼표 없이 각각 한 줄씩 입력해 결과를 확인하세요.","skill":"입출력 적용 · 여러 입력의 계산 연결","solution":{"answer":"예시 답: 세 입력을 각각 int로 바꾸고, 낸 돈에서 가격과 개수를 곱한 값을 뺍니다. 주어진 입력에서는 6400이 출력됩니다.","code":{"source":"paid = int(input())\nprice = int(input())\ncount = int(input())\nchange = paid - price * count\nprint(change)","kind":"python","output":"6400","error":null,"input":"10000\n1200\n3\n","caption":"첫 줄은 낸 돈, 둘째 줄은 가격, 셋째 줄은 개수입니다."}},"explanation":"input을 적은 순서와 값을 넣는 순서가 맞아야 각 이름이 의도한 수에 연결됩니다. 가격 1200과 개수 3을 먼저 곱한 뒤 10000에서 빼므로 6400이 남습니다.","related":["python-l006","python-l007","python-l008","python-l010"]},{"question":"직사각형의 가로와 세로를 미터 단위로 두 줄 입력받으세요. 소수 입력을 허용하며 먼저 넓이를 출력하고, 다음 줄에는 넓이가 6.0제곱미터 이상인지 True 또는 False로 출력하는 프로그램을 작성하세요. 첫 줄 3.5, 둘째 줄 2를 입력해 확인하세요.","skill":"입출력 적용 · 실수 계산과 불리언 출력","solution":{"answer":"예시 답: 가로와 세로를 float로 바꾸어 곱하면 7.0입니다. 이 값은 6.0 이상이므로 다음 줄에는 True가 출력됩니다.","code":{"source":"width = float(input())\nheight = float(input())\narea = width * height\nprint(area)\nprint(area >= 6.0)","kind":"python","output":"7.0\nTrue","error":null,"input":"3.5\n2\n","caption":"2도 float로 변환하므로 2.0으로 계산에 참여합니다."}},"explanation":"읽은 문자열을 float로 바꾸면 소수 부분을 유지한 채 넓이를 계산할 수 있습니다. area >= 6.0은 값을 바꾸는 대입이 아니라 비교이며, 그 결과인 불리언을 별도의 줄에 출력합니다.","related":["python-l007","python-l008","python-l009","python-l010"]}]}];
